#!/usr/bin/env node

const { PrismaClient } = require('@prisma/client');
const bcrypt = require('bcrypt');

const prisma = new PrismaClient();

async function seedUsers() {
  try {
    console.log('Starting user seeding...');

    // Step 1: Create or get the default organization
    let organization = await prisma.organization.findFirst({
      where: { slug: 'default' },
    });

    if (!organization) {
      console.log('Creating default organization...');
      organization = await prisma.organization.create({
        data: {
          name: 'Default Organization',
          slug: 'default',
        },
      });
      console.log('✅ Organization created:', organization.id);
    } else {
      console.log('Using existing organization:', organization.id);
    }

    // Step 2: Create or ensure subscription tier exists for the organization
    let subscriptionTier = await prisma.subscriptionTier.findFirst({
      where: { organizationId: organization.id },
    });

    if (!subscriptionTier) {
      console.log('Creating subscription tier for organization...');
      subscriptionTier = await prisma.subscriptionTier.create({
        data: {
          organizationId: organization.id,
          tierLevel: 'professional',
          status: 'active',
          billingCycle: 'monthly',
        },
      });
      console.log('✅ Subscription tier created:', subscriptionTier.id);
    } else {
      console.log(
        'Subscription tier exists:',
        subscriptionTier.id,
        'Status:',
        subscriptionTier.status,
      );
    }

    // Step 3: Hash the default PINs
    const managerPinHash = await bcrypt.hash('5624', 10);
    const staffPinHash = await bcrypt.hash('1234', 10);

    // Step 4: Create or update default users with organization assigned
    const managerUser = await prisma.user.upsert({
      where: { id: 1 },
      update: {
        role: 'Manager',
        pin: managerPinHash,
        organizationId: organization.id,
      },
      create: {
        id: 1,
        role: 'Manager',
        pin: managerPinHash,
        organizationId: organization.id,
      },
    });

    const staffUser = await prisma.user.upsert({
      where: { id: 2 },
      update: {
        role: 'Staff',
        pin: staffPinHash,
        organizationId: organization.id,
      },
      create: {
        id: 2,
        role: 'Staff',
        pin: staffPinHash,
        organizationId: organization.id,
      },
    });

    console.log('✅ User seeding completed successfully');

    console.log('\n✅ Default organization and users created:');
    console.log('   Organization: Default Organization');
    console.log('   Manager: PIN 5624 (Role: Manager)');
    console.log('   Staff:   PIN 1234 (Role: Staff)');
    console.log('\nYou can now log in with either PIN.');
  } catch (error) {
    console.error('User seeding failed:', error.message);
    process.exit(1);
  } finally {
    await prisma.$disconnect();
  }
}

// Run the seeding function
seedUsers();

import { Request, Response, NextFunction } from 'express';
import jwt, { Secret } from 'jsonwebtoken';
import { verifyToken as verifyClerkToken } from '@clerk/backend';
import { AnalyticsService, AnalyticsEventType } from '../services/analytics.service';
import { BillingCycle, TierLevel, SubscriptionStatus } from '../types/subscription';
import { getDefaultDatabaseClient } from '../database/database-factory';
import { envConfig } from '../config/environment';
import { SubscriptionService } from '../services/subscription.service';

export interface AuthRequest extends Request {
  userId?: number;
  userRole?: string;
  organizationId?: string;
  tierLevel?: TierLevel;
  user?: {
    id: number;
    role: string;
    organizationId: string;
    tierLevel: TierLevel;
  };
}

export interface TokenPayload extends jwt.JwtPayload {
  userId: number;
  role: string;
  organizationId: string;
  tierLevel: TierLevel;
}

interface ClerkTokenPayload {
  sub: string;
  exp?: number;
}

const CLERK_DEV_ORIGINS = ['http://localhost:3002', 'http://127.0.0.1:3002'];

function getAuthorizedParties(): string[] {
  const partySet = new Set<string>(CLERK_DEV_ORIGINS);

  if (envConfig.FRONTEND_URL) {
    partySet.add(envConfig.FRONTEND_URL);
  }

  if (envConfig.CORS_ORIGIN) {
    partySet.add(envConfig.CORS_ORIGIN);
  }

  const parties = Array.from(partySet);
  if (parties.length === CLERK_DEV_ORIGINS.length && process.env.NODE_ENV === 'production') {
    console.warn(
      'WARNING: No production origins configured for Clerk token verification. Please set FRONTEND_URL or CORS_ORIGIN.',
    );
  }

  return parties;
}

const isTierLevel = (value: string): value is TierLevel =>
  ['starter', 'professional', 'premium', 'concierge'].includes(value as TierLevel);

const isBillingCycle = (value: string): value is BillingCycle =>
  Object.values(BillingCycle).includes(value as BillingCycle);

const hasRequiredTokenFields = (token: any): boolean => {
  return 'userId' in token && 'role' in token && 'organizationId' in token && 'tierLevel' in token;
};

// Simple memory cache for subscription status
const subscriptionCache = new Map<string, { subscription: any; timestamp: number }>();
const CACHE_TTL_MS = 5 * 60 * 1000; // 5 minutes
export const TEST_AUTH_BYPASS_ORG_ID = 'default-org';

export const authenticateToken = async (req: AuthRequest, res: Response, next: NextFunction) => {
  // Test environment bypass
  if (process.env.NODE_ENV === 'test' && process.env.TEST_AUTH_BYPASS === 'true') {
    req.user = {
      id: 1,
      role: 'Manager',
      organizationId: TEST_AUTH_BYPASS_ORG_ID,
      tierLevel: 'professional',
    };
    req.userId = 1;
    req.userRole = 'Manager';
    req.organizationId = TEST_AUTH_BYPASS_ORG_ID;
    req.tierLevel = 'professional';
    return next();
  }

  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (token === undefined || token === null) {
    // Track unauthorized access attempt
    const analyticsService = AnalyticsService.getInstance();
    analyticsService.trackEvent({
      eventType: AnalyticsEventType.USER_LOGOUT,
      eventCategory: 'Auth',
      eventAction: 'unauthorized_access_attempt',
      ipAddress: req.ip,
      userAgent: req.get('User-Agent') || undefined,
      metadata: { path: req.path, method: req.method },
    });

    return res.status(401).json({ message: 'Access denied: No token provided' }); // No token
  }

  // Check for valid token with current secret and old secret.
  // If both fail, fall back to Clerk JWT verification for migrated clients.
  let decodedToken: TokenPayload | string | null = null;

  const resolveFromClerkToken = async (): Promise<TokenPayload | null> => {
    if (!envConfig.CLERK_SECRET_KEY) {
      return null;
    }

    try {
      const clerkDecoded = (await verifyClerkToken(token, {
        secretKey: envConfig.CLERK_SECRET_KEY,
        authorizedParties: getAuthorizedParties(),
      })) as ClerkTokenPayload;

      const prisma = getDefaultDatabaseClient();

      const user = await prisma.user.findUnique({
        where: { clerkUserId: clerkDecoded.sub },
        select: {
          id: true,
          role: true,
          organizationId: true,
        },
      });

      if (!user?.organizationId) {
        return null;
      }

      const subscription = await prisma.subscriptionTier.findFirst({
        where: { organizationId: user.organizationId },
        orderBy: { createdAt: 'desc' },
      });

      if (!subscription) {
        return null;
      }

      const normalizedTier = subscription.tierLevel.toLowerCase();
      if (!isTierLevel(normalizedTier)) {
        return null;
      }

      return {
        userId: user.id,
        role: user.role,
        organizationId: user.organizationId,
        tierLevel: normalizedTier,
        exp: clerkDecoded.exp,
      };
    } catch {
      return null;
    }
  };

  // First try with the current JWT secret
  try {
    decodedToken = jwt.verify(token, envConfig.JWT_SECRET) as TokenPayload;
  } catch (_err) {
    // If current secret fails, try with old secret (for rotation period)
    if (process.env.JWT_SECRET_OLD) {
      try {
        decodedToken = jwt.verify(token, process.env.JWT_SECRET_OLD) as TokenPayload;
      } catch (_rotationErr) {
        decodedToken = await resolveFromClerkToken();
      }
    } else {
      decodedToken = await resolveFromClerkToken();
    }

    if (!decodedToken) {
      // JWT verification failed and Clerk fallback also failed.
      // Track invalid token attempt.
      const analyticsService = AnalyticsService.getInstance();
      analyticsService.trackEvent({
        eventType: AnalyticsEventType.USER_LOGOUT,
        eventCategory: 'Auth',
        eventAction: 'invalid_token_attempt',
        ipAddress: req.ip,
        userAgent: req.get('User-Agent') || undefined,
        metadata: { path: req.path, method: req.method },
      });

      return res.status(403).json({ message: 'Access denied: Invalid token' });
    }
  }

  // Check for expected object structure
  if (!decodedToken || typeof decodedToken !== 'object') {
    // Track invalid token payload
    const analyticsService = AnalyticsService.getInstance();
    analyticsService.trackEvent({
      eventType: AnalyticsEventType.USER_LOGOUT,
      eventCategory: 'Auth',
      eventAction: 'invalid_token_payload',
      ipAddress: req.ip,
      userAgent: req.get('User-Agent') || undefined,
      metadata: { path: req.path, method: req.method },
    });

    return res.status(403).json({ message: 'Access denied: Invalid token payload' });
  }

  // Validate required fields exist in the token payload
  if (!hasRequiredTokenFields(decodedToken)) {
    const analyticsService = AnalyticsService.getInstance();
    analyticsService.trackEvent({
      eventType: AnalyticsEventType.USER_LOGOUT,
      eventCategory: 'Auth',
      eventAction: 'missing_token_fields',
      ipAddress: req.ip,
      userAgent: req.get('User-Agent') || undefined,
      metadata: { path: req.path, method: req.method },
    });

    return res.status(403).json({ message: 'Access denied: Malformed token payload' });
  }

  // Check for token expiration (manually if not automatically handled by jwt.verify)
  if (decodedToken.exp && decodedToken.exp * 1000 < Date.now()) {
    // Track expired token attempt
    const analyticsService = AnalyticsService.getInstance();
    analyticsService.trackEvent({
      eventType: AnalyticsEventType.USER_LOGOUT,
      eventCategory: 'Auth',
      eventAction: 'expired_token_attempt',
      ipAddress: req.ip,
      userAgent: req.get('User-Agent') || undefined,
      metadata: { path: req.path, method: req.method },
    });

    return res.status(403).json({ message: 'Access denied: Token has expired' });
  }

  // Validate required multi-tenant fields
  if (!decodedToken.organizationId || !decodedToken.tierLevel) {
    const analyticsService = AnalyticsService.getInstance();
    analyticsService.trackEvent({
      eventType: AnalyticsEventType.USER_LOGOUT,
      eventCategory: 'Auth',
      eventAction: 'missing_tenant_context',
      ipAddress: req.ip,
      userAgent: req.get('User-Agent') || undefined,
      metadata: { path: req.path, method: req.method },
    });

    return res.status(403).json({ message: 'Access denied: Missing tenant context in token' });
  }

  // Validate organization exists and is active (task 4.4)
  try {
    const orgId = decodedToken.organizationId;
    let subscription: any = null;
    let hasActiveAccess = true;

    // Check cache first
    const cached = subscriptionCache.get(orgId);
    if (cached && Date.now() - cached.timestamp < CACHE_TTL_MS) {
      subscription = cached.subscription.data;
      hasActiveAccess = cached.subscription.hasActiveAccess;
    } else {
      const prisma = getDefaultDatabaseClient();
      subscription = await prisma.subscriptionTier.findFirst({
        where: { organizationId: orgId },
        orderBy: { createdAt: 'desc' },
      });

      if (subscription && subscription.status === SubscriptionStatus.CANCELED) {
        const tierLevel = isTierLevel(subscription.tierLevel) ? subscription.tierLevel : null;
        const billingCycle = isBillingCycle(subscription.billingCycle)
          ? subscription.billingCycle
          : null;

        if (tierLevel && billingCycle) {
          const subscriptionService = new SubscriptionService(prisma);
          hasActiveAccess = await subscriptionService.isAccessActive({
            id: subscription.id,
            organizationId: subscription.organizationId,
            tierLevel,
            stripeSubscriptionId: subscription.stripeSubscriptionId ?? undefined,
            trialEndDate: subscription.trialEndDate ?? undefined,
            trialStartedAt: subscription.trialStartedAt ?? undefined,
            trialConvertedAt: subscription.trialConvertedAt ?? undefined,
            status: subscription.status,
            billingCycle,
            createdAt: subscription.createdAt,
            updatedAt: subscription.updatedAt,
          });
        } else {
          hasActiveAccess = false;
        }
      }

      // Update cache
      subscriptionCache.set(orgId, {
        subscription: { data: subscription, hasActiveAccess },
        timestamp: Date.now(),
      });
    }

    if (!subscription) {
      const analyticsService = AnalyticsService.getInstance();
      analyticsService.trackEvent({
        userId: decodedToken.userId,
        eventType: AnalyticsEventType.USER_LOGOUT,
        eventCategory: 'Auth',
        eventAction: 'organization_subscription_not_found',
        ipAddress: req.ip,
        userAgent: req.get('User-Agent') || undefined,
        metadata: {
          organizationId: decodedToken.organizationId,
          path: req.path,
          method: req.method,
        },
      });

      return res.status(403).json({
        message: 'Access denied: Organization subscription not configured',
      });
    }

    // Check if subscription is canceled (allow access until Stripe period end if applicable)
    if (subscription.status === SubscriptionStatus.CANCELED) {
      const tierLevel = isTierLevel(subscription.tierLevel) ? subscription.tierLevel : null;
      const billingCycle = isBillingCycle(subscription.billingCycle)
        ? subscription.billingCycle
        : null;

      if (!tierLevel || !billingCycle) {
        const analyticsService = AnalyticsService.getInstance();
        analyticsService.trackEvent({
          userId: decodedToken.userId,
          eventType: AnalyticsEventType.USER_LOGOUT,
          eventCategory: 'Auth',
          eventAction: 'organization_subscription_invalid',
          ipAddress: req.ip,
          userAgent: req.get('User-Agent') || undefined,
          metadata: {
            organizationId: decodedToken.organizationId,
            path: req.path,
            method: req.method,
            subscriptionTierLevel: subscription.tierLevel,
            subscriptionBillingCycle: subscription.billingCycle,
          },
        });

        return res.status(403).json({
          message: 'Access denied: Organization subscription is invalid. Please contact support.',
        });
      }

      if (!hasActiveAccess) {
        const analyticsService = AnalyticsService.getInstance();
        analyticsService.trackEvent({
          userId: decodedToken.userId,
          eventType: AnalyticsEventType.USER_LOGOUT,
          eventCategory: 'Auth',
          eventAction: 'organization_subscription_canceled',
          ipAddress: req.ip,
          userAgent: req.get('User-Agent') || undefined,
          metadata: {
            organizationId: decodedToken.organizationId,
            path: req.path,
            method: req.method,
          },
        });

        return res.status(403).json({
          message:
            'Access denied: Organization subscription has been canceled. Please contact support.',
        });
      }
    }
  } catch (error) {
    const analyticsService = AnalyticsService.getInstance();
    analyticsService.trackEvent({
      userId: decodedToken.userId,
      eventType: AnalyticsEventType.USER_LOGOUT,
      eventCategory: 'Auth',
      eventAction: 'organization_validation_error',
      ipAddress: req.ip,
      userAgent: req.get('User-Agent') || undefined,
      metadata: {
        organizationId: decodedToken.organizationId,
        path: req.path,
        method: req.method,
        error: error instanceof Error ? error.message : 'Unknown error',
      },
    });

    return res.status(500).json({
      message: 'Error validating organization access',
    });
  }

  // Now that we've verified, we can safely access the properties
  req.userId = decodedToken.userId;
  req.userRole = decodedToken.role;
  req.organizationId = decodedToken.organizationId;
  req.tierLevel = decodedToken.tierLevel;
  req.user = {
    id: decodedToken.userId,
    role: decodedToken.role,
    organizationId: decodedToken.organizationId,
    tierLevel: decodedToken.tierLevel,
  };

  // Track successful authenticated request
  const analyticsService = AnalyticsService.getInstance();
  analyticsService.trackEvent({
    userId: decodedToken.userId,
    eventType: AnalyticsEventType.VIEW_DASHBOARD, // General action for accessing protected routes
    eventCategory: 'Auth',
    eventAction: 'protected_route_access',
