// Function to generate a JWT token with configurable expiration
export const generateToken = (
  userId: number,
  role: string,
  organizationId: string,
  tierLevel: TierLevel,
  expiresIn: string | number = '24h',
): string => {
  return jwt.sign({ userId, role, organizationId, tierLevel }, envConfig.JWT_SECRET, {
    expiresIn: expiresIn as any,
  });
};

export const requireManager = (req: AuthRequest, res: Response, next: NextFunction) => {
  if (req.userRole !== 'Manager' && req.userRole !== 'admin') {
    // Track unauthorized manager access attempt
    const analyticsService = AnalyticsService.getInstance();
    analyticsService.trackEvent({
      userId: req.userId,
      eventType: AnalyticsEventType.USER_LOGOUT,
      eventCategory: 'Auth',
      eventAction: 'manager_access_denied',
      ipAddress: req.ip,
      userAgent: req.get('User-Agent') || undefined,
      metadata: { path: req.path, method: req.method, role: req.userRole },
    });

    return res.status(403).json({ message: 'Access denied: Manager role required' });
  }
  next();
};

import { Request, Response, NextFunction } from 'express';
import { Logger } from '../utils/logger';
import { BaseError, isBaseError, ValidationError, InternalError } from '../errors';

/**
 * Type-safe error payload structure
 */
interface ErrorPayload {
  code: string;
  message: string;
  statusCode: number;
  errors?: Record<string, unknown>[];
  stack?: string;
}

/**
 * Enhanced Error Handler Middleware (Phase 13)
 *
 * Handles both custom BaseError instances and generic Error objects.
 * Provides standardized JSON responses with appropriate HTTP status codes.
 * Logs errors with context for debugging and monitoring.
 */
export const errorHandler = (err: Error, req: Request, res: Response, _next: NextFunction) => {
  // Prevent multiple responses
  if (res.headersSent) {
    return _next(err);
  }

  // Determine status code and error payload
  let statusCode = 500;
  let errorPayload: ErrorPayload = {
    code: 'INTERNAL_ERROR',
    message: 'An unexpected error occurred',
    statusCode: 500,
  };

  if (isBaseError(err)) {
    // Custom error - use its properties
    statusCode = err.statusCode;
    errorPayload = {
      code: err.code,
      message: err.message,
      statusCode: err.statusCode,
    };

    // Include validation errors if present
    if (err instanceof ValidationError && err.errors) {
      errorPayload.errors = err.errors;
    }
  } else {
    // Generic Error - treat as internal error
    const isDevelopment = process.env.NODE_ENV === 'development';
    errorPayload.message = isDevelopment ? err.message : 'An unexpected error occurred';

    // Include stack trace in development
    if (isDevelopment && err.stack) {
      errorPayload.stack = err.stack;
    }
  }

  // Log the error with additional context
  Logger.error(`Request Error: ${err.message}`, {
    code: errorPayload.code,
    statusCode,
    url: req.url,
    method: req.method,
    ip: req.ip,
    userAgent: req.get('User-Agent'),
    userId: (req as any).userId,
    stack: err.stack,
  });

  // Send error response
  res.status(statusCode).json(errorPayload);
};

/**
 * Rate Limiting Middleware for Phase 13 Security Hardening
 *
 * Provides rate limiting with different presets:
 * - standard: 100 requests per 15 minutes
 * - strict: 5 requests per 15 minutes (for login/register)
 * - upload: 10 requests per 1 hour (for file uploads)
 *
 * Uses express-rate-limit for flexible, in-memory rate limiting.
 */

import rateLimit from 'express-rate-limit';
import { Request, Response } from 'express';
import { envConfig } from '../config/environment';
import { Logger } from '../utils/logger';

/**
 * Standard rate limiter: 100 requests per 15 minutes
 * Used for general API endpoints
 */
export const standardLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  statusCode: 429,
  skipSuccessfulRequests: false, // Count successful requests
  skipFailedRequests: false, // Count failed requests
  handler: (req: Request, res: Response) => {
    Logger.warn('Rate limit exceeded (standard)', {
      ip: (req.headers['x-forwarded-for'] as string) || req.ip,
      endpoint: req.path,
      method: req.method,
    });
    res.status(429).json({
      code: 'RATE_LIMIT_EXCEEDED',
      message: 'Too many requests from this IP, please try again later.',
      retryAfter: (req as any).rateLimit?.resetTime
        ? new Date((req as any).rateLimit.resetTime).toISOString()
        : undefined,
    });
  },
  store: undefined, // Uses default memory store (fine for single-instance, use Redis for distributed)
});

/**
 * Strict rate limiter: 5 requests per 15 minutes
 * Used for authentication endpoints (login, register) to prevent brute force
 */
export const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 5, // Limit each IP to 5 requests per windowMs
  message: 'Too many login attempts, please try again later.',
  statusCode: 429,
  skipSuccessfulRequests: false,
  skipFailedRequests: false,
  handler: (req: Request, res: Response) => {
    Logger.warn('Rate limit exceeded (strict)', {
      ip: (req.headers['x-forwarded-for'] as string) || req.ip,
      endpoint: req.path,
      method: req.method,
    });
    res.status(429).json({
      code: 'RATE_LIMIT_EXCEEDED',
