import jwt from 'jsonwebtoken';
import bcrypt from 'bcrypt';
import { PrismaClient } from '@prisma/client';
import { getDefaultDatabaseClient } from '../database/database-factory';
import { Logger } from '../utils/logger';
import { AuthenticationError, InternalError } from '../errors';
import { TierLevel, SubscriptionStatus } from '../types/subscription';
import { envConfig } from '../config/environment';
import crypto from 'crypto';

export interface TokenPair {
  accessToken: string;
  refreshToken: string;
}

export interface TokenPayload {
  userId: number;
  role: string;
  organizationId: string;
  tierLevel: TierLevel;
  iat?: number;
  exp?: number;
}

export interface LoginResponse {
  token: string;
  userId: number;
  role: string;
  organizationId: string;
  tierLevel: TierLevel;
}

export class AuthService {
  private prisma: PrismaClient;
  private readonly ACCESS_TOKEN_EXPIRY = '1h';
  private readonly REFRESH_TOKEN_EXPIRY = '7d';

  constructor(prismaClient?: PrismaClient) {
    this.prisma = prismaClient ?? getDefaultDatabaseClient();
  }

  // Validate PIN strength: 4-6 digits, not too predictable
  validatePin(pin: string): { isValid: boolean; message?: string } {
    // Check if PIN is only digits and within length limits
    if (!/^\d{4,6}$/.test(pin)) {
      return {
        isValid: false,
        message: 'PIN must be 4-6 digits long and contain only numbers',
      };
    }

    // Check for common predictable patterns
    if (this.isPredictablePattern(pin)) {
      return {
        isValid: false,
        message: 'PIN contains predictable patterns (e.g. 1234, 1111, etc.) and is not secure',
      };
    }

    return { isValid: true };
  }

  // Check for predictable patterns in the PIN
  private isPredictablePattern(pin: string): boolean {
    // Check for repeating digits (e.g., 1111, 2222)
    if (/^(\d)\1{3,}$/.test(pin)) {
      return true;
    }

    // Check for sequential digits (e.g., 1234, 4321)
    if (this.isSequential(pin)) {
      return true;
    }

    // Check for common patterns like 2580 (vertical on keypad)
    const commonPatterns = [
      '1234',
      '2345',
      '3456',
      '4567',
      '5678',
      '6789',
      '7890',
      '0987',
      '9876',
      '8765',
      '7654',
      '6543',
      '5432',
      '4321',
      '1111',
      '2222',
      '3333',
      '4444',
      '5555',
      '6666',
      '7777',
      '8888',
      '9999',
      '0000',
      '2580',
      '0852',
      '1470',
      '0741',
    ];
    return commonPatterns.includes(pin);
  }

  // Check if the PIN has sequential digits
  private isSequential(pin: string): boolean {
    let isSequential = true;
    // Check increasing sequence
    for (let i = 1; i < pin.length; i++) {
      if (parseInt(pin[i], 10) !== parseInt(pin[i - 1], 10) + 1) {
        isSequential = false;
        break;
      }
    }

    if (isSequential) return true;

    // Check decreasing sequence
    isSequential = true;
    for (let i = 1; i < pin.length; i++) {
      if (parseInt(pin[i], 10) !== parseInt(pin[i - 1], 10) - 1) {
        isSequential = false;
        break;
      }
    }

    return isSequential;
  }

  async hashPin(pin: string): Promise<string> {
    const saltRounds = 10;
    return await bcrypt.hash(pin, saltRounds);
  }

  async verifyPin(pin: string, hashedPin: string): Promise<boolean> {
    return await bcrypt.compare(pin, hashedPin);
  }

  async login(pin: string): Promise<LoginResponse> {
    try {
      // Get all users and iterate through them to find a match
      const users = await this.prisma.user.findMany({
        select: {
          id: true,
          role: true,
          organizationId: true,
        },
      });
      Logger.debug('Auth service: Attempting to authenticate user', {
        userCount: users.length,
      });

      // Look for a user whose hashed pin matches the PIN that was provided
      for (const user of users) {
        Logger.debug('Auth service: Checking user for authentication', { userId: user.id });

        const isValidPin = false; // PIN auth removed — use Clerk authentication
        if (isValidPin) {
          // Verify user has an organization
          if (!user.organizationId) {
            Logger.error('Auth service: User has no organization assigned', { userId: user.id });
            throw new AuthenticationError('User organization not configured');
          }

          // Query organization and its subscription tier
          const subscriptionTier = await this.prisma.subscriptionTier.findFirst({
            where: { organizationId: user.organizationId },
            orderBy: { createdAt: 'desc' },
          });

          if (!subscriptionTier) {
            Logger.error('Auth service: No subscription tier found for organization', {
              organizationId: user.organizationId,
            });
            throw new AuthenticationError('Organization subscription not configured');
          }

          // Verify organization subscription is not canceled
          if (subscriptionTier.status === SubscriptionStatus.CANCELED) {
            Logger.warn('Auth service: Login attempt for canceled organization', {
              organizationId: user.organizationId,
              userId: user.id,
            });
            throw new AuthenticationError(
              'Organization subscription has been canceled. Please contact support.',
            );
          }

          Logger.info('Auth service: User authenticated successfully', {
            userId: user.id,
            organizationId: user.organizationId,
            tierLevel: subscriptionTier.tierLevel,
            role: user.role,
          });

          const token = jwt.sign(
            {
              userId: user.id,
              role: user.role,
              organizationId: user.organizationId,
              tierLevel: subscriptionTier.tierLevel,
            },
            envConfig.JWT_SECRET,
            {
              expiresIn: '1h', // Token expires in 1 hour
            },
          );

          return {
            token,
            userId: user.id,
            role: user.role,
            organizationId: user.organizationId,
            tierLevel: subscriptionTier.tierLevel as TierLevel,
          };
        }
      }

      Logger.warn('Auth service: Authentication failed for provided PIN');
      throw new AuthenticationError('Invalid PIN');
    } catch (error) {
      if (error instanceof AuthenticationError) {
        throw error;
      }
      Logger.error('Auth service: Error during authentication', {
        error: error instanceof Error ? error.message : 'Unknown error',
        stack: error instanceof Error ? error.stack : undefined,
      });
      throw new InternalError('Authentication failed');
    }
  }

  /**
   * Generate both access and refresh tokens for a user
   */
  async generateTokens(userId: number, role: string): Promise<TokenPair> {
    try {
      const secret = envConfig.JWT_SECRET;

      // Generate access token (short-lived)
      const accessToken = jwt.sign({ userId, role }, secret, {
        expiresIn: this.ACCESS_TOKEN_EXPIRY,
      });

      // Generate refresh token (long-lived)
      const refreshToken = crypto.randomBytes(64).toString('hex');
      const expiresAt = new Date();
      expiresAt.setDate(expiresAt.getDate() + 7); // 7 days from now

      // Store refresh token in database
      await this.prisma.refreshToken.create({
        data: {
          userId,
          token: refreshToken,
          expiresAt,
        },
      });

      Logger.info('Auth service: Generated token pair', { userId });
      return { accessToken, refreshToken };
    } catch (error) {
      Logger.error('Auth service: Error generating tokens', {
        error: error instanceof Error ? error.message : 'Unknown error',
      });
      throw new InternalError('Token generation failed');
    }
  }

  /**
   * Verify and decode a JWT access token
   */
  verifyToken(token: string): TokenPayload {
    try {
      const secret = envConfig.JWT_SECRET;
      const decoded = jwt.verify(token, secret) as TokenPayload;
      return decoded;
    } catch (error) {
      Logger.warn('Auth service: Token verification failed', {
        error: error instanceof Error ? error.message : 'Unknown error',
      });
      throw new AuthenticationError('Invalid or expired token');
    }
  }

  /**
   * Refresh access token using a valid refresh token
   */
  async refreshAccessToken(refreshToken: string): Promise<string> {
    try {
      // Find refresh token in database
      const storedToken = await this.prisma.refreshToken.findUnique({
        where: { token: refreshToken },
        include: { user: true },
      });

      if (!storedToken) {
        Logger.warn('Auth service: Refresh token not found');
        throw new AuthenticationError('Invalid refresh token');
      }

      // Check if token is expired
      if (storedToken.expiresAt < new Date()) {
        // Clean up expired token
        await this.prisma.refreshToken.delete({ where: { id: storedToken.id } });
        Logger.warn('Auth service: Refresh token expired', { userId: storedToken.userId });
        throw new AuthenticationError('Refresh token expired');
      }

      // Check if token is revoked
      if (storedToken.revokedAt) {
        Logger.warn('Auth service: Refresh token revoked', { userId: storedToken.userId });
        throw new AuthenticationError('Refresh token revoked');
      }

      // Generate new access token
      const secret = envConfig.JWT_SECRET;
      const accessToken = jwt.sign(
        { userId: storedToken.userId, role: storedToken.user.role },
        secret,
        { expiresIn: this.ACCESS_TOKEN_EXPIRY },
      );

      Logger.info('Auth service: Access token refreshed', { userId: storedToken.userId });
      return accessToken;
    } catch (error) {
      if (error instanceof AuthenticationError) {
        throw error;
      }
      Logger.error('Auth service: Error refreshing access token', {
        error: error instanceof Error ? error.message : 'Unknown error',
      });
      throw new InternalError('Token refresh failed');
    }
  }

  /**
   * Revoke a refresh token (e.g., on logout)
   */
  async revokeRefreshToken(refreshToken: string): Promise<void> {
    try {
      const storedToken = await this.prisma.refreshToken.findUnique({
        where: { token: refreshToken },
      });

      if (!storedToken) {
        Logger.warn('Auth service: Attempt to revoke non-existent token');
        return; // Silently succeed if token doesn't exist
      }

      await this.prisma.refreshToken.update({
        where: { id: storedToken.id },
        data: { revokedAt: new Date() },
      });

      Logger.info('Auth service: Refresh token revoked', { userId: storedToken.userId });
    } catch (error) {
      Logger.error('Auth service: Error revoking token', {
        error: error instanceof Error ? error.message : 'Unknown error',
      });
      throw new InternalError('Token revocation failed');
    }
  }

  /**
   * Clean up expired refresh tokens (should be run periodically)
   */
  async cleanupExpiredTokens(): Promise<number> {
    try {
      const result = await this.prisma.refreshToken.deleteMany({
        where: {
          expiresAt: { lt: new Date() },
        },
      });

      Logger.info('Auth service: Cleaned up expired tokens', { count: result.count });
      return result.count;
    } catch (error) {
      Logger.error('Auth service: Error cleaning up expired tokens', {
        error: error instanceof Error ? error.message : 'Unknown error',
      });
      return 0;
    }
  }
}

/**
 * Clerk Webhook Handler Service
 *
 * Implements Clerk webhook verification and processing with idempotent handling.
 * Handles user.created, user.updated, and organization.created events.
 *
 * Handler sequence (required):
 * 1. Verify signature first (reject invalid with 4xx)
 * 2. Parse payload second (after verification)
 * 3. Handle idempotently (check event ID, process, store)
 */

import { Response } from 'express';
import { PrismaClient } from '@prisma/client';
import { envConfig } from '../config/environment';
import { getDefaultDatabaseClient } from '../database/database-factory';
import { SubscriptionService } from './subscription.service';
import { Webhook } from 'svix';
import * as Sentry from '@sentry/node';
import { ApplicationMonitoringService } from './application.monitoring.service';

// Simple logging utility
const log = {
  info: (message: string, data?: Record<string, unknown>) => {
    console.log(`[CLERK_WEBHOOK] ${message}`, data ? JSON.stringify(data) : '');
  },
  warn: (message: string, data?: Record<string, unknown>) => {
    console.warn(`[CLERK_WEBHOOK] ${message}`, data ? JSON.stringify(data) : '');
  },
  error: (message: string, data?: Record<string, unknown>) => {
    console.error(`[CLERK_WEBHOOK] ${message}`, data ? JSON.stringify(data) : '');
  },
};

export class ClerkWebhookService {
  private prisma: PrismaClient;
  private subscriptionService: SubscriptionService;
  private monitor: ApplicationMonitoringService;

  constructor(prismaClient?: PrismaClient, subscriptionService?: SubscriptionService) {
    this.prisma = prismaClient ?? getDefaultDatabaseClient();
    this.subscriptionService = subscriptionService ?? new SubscriptionService(this.prisma);
    this.monitor = ApplicationMonitoringService.getInstance();
  }

  /**
   * Verify Clerk webhook signature using Svix
   */
  verifySignature(payload: Buffer, headers: Record<string, string>): unknown {
    if (!envConfig.CLERK_WEBHOOK_SECRET) {
      throw new Error('CLERK_WEBHOOK_SECRET is not configured');
    }

    const wh = new Webhook(envConfig.CLERK_WEBHOOK_SECRET);

    // Get the svix-specific headers
    const svixId = headers['svix-id'];
    const svixTimestamp = headers['svix-timestamp'];
    const svixSignature = headers['svix-signature'];

    if (!svixId || !svixTimestamp || !svixSignature) {
      throw new Error('Missing required Svix headers');
    }

    // Verify the webhook
    return wh.verify(payload.toString(), {
      'svix-id': svixId,
      'svix-timestamp': svixTimestamp,
      'svix-signature': svixSignature,
    });
  }

  /**
   * Check if this is a new event (idempotency check)
   */
  async isNewEvent(eventId: string): Promise<boolean> {
    try {
      const existingEvent = await this.prisma.clerkWebhookEvent.findUnique({
        where: { id: eventId },
      });
      return !existingEvent;
    } catch (error) {
      log.error('Error checking webhook event idempotency', { eventId, error });
      // If we can't check, assume it's new to avoid missing events
      return true;
    }
  }

  /**
   * Mark an event as processed
   */
  async markEventProcessed(eventId: string, eventType: string): Promise<void> {
    try {
      await this.prisma.clerkWebhookEvent.create({
        data: {
          id: eventId,
          eventType,
          processedAt: new Date(),
        },
      });
    } catch (error) {
      log.error('Error marking webhook event as processed', { eventId, eventType, error });
      // Don't throw - this is cleanup, the main event already succeeded
    }
  }

  /**
   * Handle the webhook event
   */
  async handleEvent(event: any): Promise<void> {
    const { type, data } = event;

    switch (type) {
      case 'user.created':
        await this.handleUserCreated(data);
        break;
      case 'user.updated':
        await this.handleUserUpdated(data);
        break;
      case 'organization.created':
        await this.handleOrganizationCreated(data);
        break;
      case 'organizationMembership.created':
        await this.handleOrganizationMembershipCreated(data);
        break;
      case 'organizationMembership.deleted':
        await this.handleOrganizationMembershipDeleted(data);
        break;
      default:
        log.info('Unhandled webhook event type', { type });
        break;
    }
  }

  /**
   * Handle user.created event
   * Creates a user record and organization if needed
   */
  private async handleUserCreated(data: any): Promise<void> {
    const { id, email_addresses, username, first_name, last_name, organization_memberships } = data;

    try {
      // Get primary email
      const primaryEmail = email_addresses.find(
        (email: any) => email.id === data.primary_email_address_id,
      )?.email_address;

      if (!primaryEmail) {
        log.error('User created event missing primary email', { userId: id });
        return;
      }

      // Check if user already exists
      const existingUser = await this.prisma.user.findUnique({
        where: { clerkUserId: id },
      });

      if (existingUser) {
        log.info('User already exists, skipping creation', { clerkUserId: id });
        return;
      }

      // Get organization membership if user belongs to an org
      const orgMembership = organization_memberships?.[0];
      let organizationId: string | null = null;

      if (orgMembership?.organization) {
        // Find or create organization from Clerk
        const org = await this.findOrCreateOrganization(orgMembership.organization);
        organizationId = org.id;
      } else {
        // Auto-create organization for email/password signups
        const org = await this.createDefaultOrganization(id, primaryEmail);
        organizationId = org.id;
      }

      // Create user
      const user = await this.prisma.user.create({
        data: {
          clerkUserId: id,
          email: primaryEmail,
          username: username || primaryEmail.split('@')[0],
          organizationId,
          role: orgMembership?.role === 'admin' ? 'Manager' : 'Team Member',
          createdAt: new Date(),
          updatedAt: new Date(),
        },
      });

      log.info('User created successfully', {
        userId: user.id,
        clerkUserId: id,
        email: primaryEmail,
        organizationId,
      });

      // Create trial subscription for the organization
      await this.ensureTrialSubscription(organizationId, primaryEmail);
    } catch (error) {
      log.error('Error handling user.created event', { userId: id, error });
      Sentry.captureException(error, { extra: { userId: id, eventType: 'user.created' } });
      throw error;
    }
  }

  /**
   * Handle user.updated event
   */
  private async handleUserUpdated(data: any): Promise<void> {
    const { id, email_addresses, username, first_name, last_name } = data;

    try {
      // Get primary email
      const primaryEmail = email_addresses.find(
        (email: any) => email.id === data.primary_email_address_id,
      )?.email_address;

      // Update user record
      await this.prisma.user.updateMany({
        where: { clerkUserId: id },
        data: {
          email: primaryEmail,
          username: username || primaryEmail?.split('@')[0],
          updatedAt: new Date(),
        },
      });

      log.info('User updated successfully', { clerkUserId: id, email: primaryEmail });
    } catch (error) {
      log.error('Error handling user.updated event', { userId: id, error });
      Sentry.captureException(error, { extra: { userId: id, eventType: 'user.updated' } });
      throw error;
    }
  }

  /**
   * Handle organization.created event
   */
  private async handleOrganizationCreated(data: any): Promise<void> {
    const { id, name, created_by } = data;

    try {
      // Find or create organization
      const org = await this.findOrCreateOrganization({
        id,
        name,
        created_by,
      });

      log.info('Organization created/updated successfully', {
        organizationId: org.id,
        clerkOrganizationId: id,
        name,
      });
    } catch (error) {
      log.error('Error handling organization.created event', { organizationId: id, error });
      Sentry.captureException(error, {
        extra: { organizationId: id, eventType: 'organization.created' },
      });
      throw error;
    }
  }

  /**
   * Handle organizationMembership.created event
   * Links an existing user to an organization when they join
   */
  private async handleOrganizationMembershipCreated(data: any): Promise<void> {
    const { public_user_data, organization, role } = data;
    const clerkUserId = public_user_data?.user_id;
    const clerkOrgId = organization?.id;

    try {
      if (!clerkUserId || !clerkOrgId) {
        log.error('organizationMembership.created missing user or org id', { data });
        return;
      }

      // Find or create the organization
      const org = await this.findOrCreateOrganization(organization);

      // Map Clerk role to app role
      const appRole = role === 'org:admin' ? 'Manager' : 'Team Member';

      // Link user to organization
      const updated = await this.prisma.user.updateMany({
        where: { clerkUserId },
        data: {
          organizationId: org.id,
          role: appRole,
          updatedAt: new Date(),
        },
      });

      if (updated.count === 0) {
        log.warn('organizationMembership.created: no user found to update', { clerkUserId });
      } else {
        log.info('User linked to organization', {
          clerkUserId,
          organizationId: org.id,
          role: appRole,
        });
      }

      // Ensure trial subscription exists for the organization
      const user = await this.prisma.user.findFirst({
        where: { clerkUserId },
        select: { email: true },
      });
      await this.ensureTrialSubscription(org.id, user?.email ?? '');
    } catch (error) {
      log.error('Error handling organizationMembership.created', {
        clerkUserId,
        clerkOrgId,
        error,
      });
      Sentry.captureException(error, {
        extra: { clerkUserId, clerkOrgId, eventType: 'organizationMembership.created' },
      });
      throw error;
    }
  }

  /**
   * Handle organizationMembership.deleted event
   * Unlinks a user from an organization when they leave/are removed
   */
  private async handleOrganizationMembershipDeleted(data: any): Promise<void> {
    const { public_user_data, organization } = data;
    const clerkUserId = public_user_data?.user_id;
    const clerkOrgId = organization?.id;

    try {
      if (!clerkUserId) {
        log.error('organizationMembership.deleted missing user id', { data });
        return;
      }

      await this.prisma.user.updateMany({
        where: { clerkUserId, organization: { clerkOrganizationId: clerkOrgId } },
        data: {
          organizationId: null,
          updatedAt: new Date(),
        },
      });

      log.info('User unlinked from organization', { clerkUserId, clerkOrgId });
    } catch (error) {
      log.error('Error handling organizationMembership.deleted', {
        clerkUserId,
        clerkOrgId,
        error,
      });
      Sentry.captureException(error, {
        extra: { clerkUserId, clerkOrgId, eventType: 'organizationMembership.deleted' },
      });
      throw error;
    }
  }

  /**
   * Find or create organization based on Clerk data
   */
  private async findOrCreateOrganization(clerkOrg: any): Promise<{ id: string }> {
    // Check if organization already exists
    let org = await this.prisma.organization.findUnique({
      where: { clerkOrganizationId: clerkOrg.id },
    });

    if (!org) {
      // Create new organization
      org = await this.prisma.organization.create({
        data: {
          clerkOrganizationId: clerkOrg.id,
          name: clerkOrg.name || 'Default Organization',
          slug: (clerkOrg.slug || clerkOrg.name || clerkOrg.id)
            .toLowerCase()
            .replace(/[^a-z0-9-]/g, '-'),
          createdAt: new Date(),
          updatedAt: new Date(),
        },
      });
    }

    return org;
  }

  /**
   * Create default organization for new email/password signups
   */
  private async createDefaultOrganization(
    clerkUserId: string,
    email: string,
  ): Promise<{ id: string }> {
    const orgName = email.split('@')[0] + "'s Organization";
    const slug = `${email.split('@')[0]}-${Date.now()}`.toLowerCase().replace(/[^a-z0-9-]/g, '-');

    const org = await this.prisma.organization.create({
      data: {
        name: orgName,
        slug: slug,
        contactEmail: email,
        createdAt: new Date(),
        updatedAt: new Date(),
      },
    });

    log.info('Created default organization for new user', {
      organizationId: org.id,
      clerkUserId,
      email,
    });

    return org;
  }

  /**
   * Ensure trial subscription exists for organization
   */
  private async ensureTrialSubscription(organizationId: string, email: string): Promise<void> {
    try {
      // Check if subscription already exists
      const existingSubscription = await this.prisma.subscriptionTier.findFirst({
        where: { organizationId },
      });

      if (existingSubscription) {
        log.info('Subscription already exists for organization', { organizationId });
        return;
      }

      // Create trial subscription
      await this.subscriptionService.createTrialSubscription(organizationId, 14);

      log.info('Trial subscription created', { organizationId, email });
    } catch (error) {
      log.error('Error creating trial subscription', { organizationId, error });
      // Don't throw - user is created, we can retry subscription later
    }
  }

  /**
   * Send success response
   */
  sendSuccess(res: Response): void {
    res.status(200).json({ received: true });
  }

  /**
   * Send error response
   */
  sendError(res: Response, message: string, statusCode: number = 400): void {
    res.status(statusCode).json({ error: message });
  }
}

// Export singleton instance
export const clerkWebhookService = new ClerkWebhookService();

import { getDb } from '../database';
import { Logger } from '../utils/logger';
import { EventEmitter } from 'events';

// Define database alert types
export enum DatabaseAlertType {
  CONNECTION_POOL_EXHAUSTED = 'CONNECTION_POOL_EXHAUSTED',
  SLOW_QUERY = 'SLOW_QUERY',
  TABLE_SIZE_THRESHOLD = 'TABLE_SIZE_THRESHOLD',
  ROW_COUNT_THRESHOLD = 'ROW_COUNT_THRESHOLD',
  DATABASE_LOCKED = 'DATABASE_LOCKED',
  DISK_SPACE_LOW = 'DISK_SPACE_LOW',
  BACKUP_FAILED = 'BACKUP_FAILED',
  HEALTH_CHECK_FAILED = 'HEALTH_CHECK_FAILED',
}

// Interface for database alert events
export interface DatabaseAlertMetadata extends Record<string, unknown> {
  query?: string;
  duration?: number;
  tableName?: string;
  rowCount?: number;
  reason?: string;
}

export interface DatabaseAlertEvent {
  type: DatabaseAlertType;
  message: string;
  severity: 'low' | 'medium' | 'high' | 'critical';
  timestamp: Date;
  metadata?: DatabaseAlertMetadata;
}

// Metrics interface for database monitoring
export interface DatabaseMetrics {
  connectionPool: {
    totalConnections: number;
    activeConnections: number;
    idleConnections: number;
    maxConnections: number;
    utilization: number; // Percentage
  };
  performance: {
    totalQueries: number;
    slowQueries: number; // Queries taking more than 100ms
    avgQueryTime: number; // in ms
    lastQueryTime: number; // in ms
  };
  health: {
    uptime: number; // in seconds
    tableSizes: { [tableName: string]: number }; // size in bytes
    rowCount: { [tableName: string]: number };
  };
  diskSpace: {
    total: number; // in bytes
    used: number; // in bytes
    free: number; // in bytes
    available: number; // in bytes
    utilization: number; // percentage
  };
  timestamp: Date;
}

// Configuration for database monitoring
export interface DatabaseMonitoringConfig {
  slowQueryThreshold: number; // in milliseconds
  alertThresholds: {
    connectionPoolUtilization: number; // percentage
    tableSizeThreshold: number; // in MB
    rowCountThreshold: number; // count
    diskSpaceUtilization: number; // percentage
  };
  checkInterval: number; // in milliseconds
  enableLogging: boolean;
  enableAlerting: boolean;
}

/**
 * Database Monitoring Service
 * Provides monitoring, metrics collection, and alerting for database operations
 */
export class DatabaseMonitoringService extends EventEmitter {
  private static instance: DatabaseMonitoringService;
  private config: DatabaseMonitoringConfig;
  private isMonitoring: boolean = false;
  private monitoringInterval?: NodeJS.Timeout;

  // Metrics store
  private metrics: DatabaseMetrics = {
    connectionPool: {
      totalConnections: 0,
      activeConnections: 0,
      idleConnections: 0,
      maxConnections: 10,
      utilization: 0,
    },
    performance: {
      totalQueries: 0,
      slowQueries: 0,
      avgQueryTime: 0,
      lastQueryTime: 0,
    },
    health: {
      uptime: 0,
      tableSizes: {},
      rowCount: {},
    },
    diskSpace: {
      total: 0,
      used: 0,
      free: 0,
      available: 0,
      utilization: 0,
    },
    timestamp: new Date(),
  };

  private constructor() {
    super();
    // Set default configuration
    this.config = {
      slowQueryThreshold: 100, // 100ms
      alertThresholds: {
        connectionPoolUtilization: 90, // 90%
        tableSizeThreshold: 100, // 100MB
        rowCountThreshold: 100000, // 100k rows
        diskSpaceUtilization: 85, // 85%
      },
      checkInterval: 30000, // 30 seconds
      enableLogging: true,
      enableAlerting: true,
    };
  }

  public static getInstance(): DatabaseMonitoringService {
    if (!DatabaseMonitoringService.instance) {
      DatabaseMonitoringService.instance = new DatabaseMonitoringService();
    }
    return DatabaseMonitoringService.instance;
  }

  /**
   * Initialize the monitoring service with configuration
   */
  public initialize(config?: Partial<DatabaseMonitoringConfig>): void {
    if (config) {
      this.config = {
        ...this.config,
        ...config,
        alertThresholds: {
          ...this.config.alertThresholds,
          ...(config.alertThresholds || {}),
        },
      };
    }

    // Start monitoring
    this.startMonitoring();
  }

  /**
   * Start the monitoring process
   */
  public startMonitoring(): void {
    if (this.isMonitoring) {
      Logger.warn('Database monitoring is already running');
      return;
    }

    this.isMonitoring = true;
    Logger.info('Database monitoring started');

    // Perform initial metrics collection
    void this.collectMetrics();

    // Set up periodic monitoring
    this.monitoringInterval = setInterval(async () => {
      try {
        await this.collectMetrics();
      } catch (error) {
        Logger.error('Error during database monitoring', {
          error: error instanceof Error ? error.message : 'Unknown error',
        });
      }
    }, this.config.checkInterval);
  }

  /**
   * Stop the monitoring process
   */
  public stopMonitoring(): void {
    if (!this.isMonitoring) {
      Logger.warn('Database monitoring is not running');
      return;
    }

    if (this.monitoringInterval) {
      clearInterval(this.monitoringInterval);
      this.monitoringInterval = undefined;
    }

    this.isMonitoring = false;
    Logger.info('Database monitoring stopped');
  }

  /**
   * Collect metrics from the database
   */
  public async collectMetrics(): Promise<DatabaseMetrics> {
    const startTime = Date.now();

    try {
      // Get connection pool metrics from the database implementation
      // In our case, we'll simulate these since better-sqlite3 doesn't expose connection pool details
      // In a real-world scenario, these would come from your connection pooling implementation
      const poolMetrics = await this.getConnectionPoolMetrics();
      this.metrics.connectionPool = poolMetrics;

      // Collect performance metrics
      this.metrics.performance = await this.getPerformanceMetrics();

      // Collect health metrics
      this.metrics.health = await this.getHealthMetrics();

      // Collect disk space metrics
      this.metrics.diskSpace = await this.getDiskSpaceMetrics();

      // Update timestamp
      this.metrics.timestamp = new Date();

      if (this.config.enableLogging) {
        Logger.debug('Database metrics collected', { metrics: this.metrics });
      }

      // Check for alerts
      await this.checkForAlerts();

      return this.metrics;
    } catch (error) {
      const duration = Date.now() - startTime;
      Logger.error('Failed to collect database metrics', {
        duration,
        error: error instanceof Error ? error.message : 'Unknown error',
      });

      // Emit alert for metrics collection failure
      this.emitAlert({
        type: DatabaseAlertType.HEALTH_CHECK_FAILED,
        message: `Failed to collect database metrics: ${error instanceof Error ? error.message : 'Unknown error'}`,
        severity: 'high',
        timestamp: new Date(),
        metadata: { duration },
      });

      throw error;
    }
  }

  /**
   * Get current database metrics
   */
  public getMetrics(): DatabaseMetrics {
    return { ...this.metrics };
  }

  /**
   * Record a query execution for performance monitoring
   */
  public recordQuery(duration: number): void {
    this.metrics.performance.totalQueries++;
    this.metrics.performance.lastQueryTime = duration;

    if (duration > this.config.slowQueryThreshold) {
      this.metrics.performance.slowQueries++;

      if (this.config.enableAlerting) {
        this.emitAlert({
          type: DatabaseAlertType.SLOW_QUERY,
          message: `Slow query detected: ${duration}ms > ${this.config.slowQueryThreshold}ms threshold`,
          severity: 'medium',
          timestamp: new Date(),
          metadata: { queryTime: duration, threshold: this.config.slowQueryThreshold },
        });
      }
    }

    // Recalculate average query time
    const totalTime =
      this.metrics.performance.avgQueryTime * (this.metrics.performance.totalQueries - 1) +
      duration;
    this.metrics.performance.avgQueryTime = totalTime / this.metrics.performance.totalQueries;
  }

  /**
   * Emit an alert event
   */
  private emitAlert(alert: DatabaseAlertEvent): void {
    if (this.config.enableAlerting) {
      this.emit('alert', alert);
      Logger.warn(`Database alert: ${alert.message}`, {
        type: alert.type,
        severity: alert.severity,
      });
    }
  }

  /**
   * Check for conditions that require alerts
   */
  private async checkForAlerts(): Promise<void> {
    // Check connection pool utilization
    if (
      this.metrics.connectionPool.utilization >
      this.config.alertThresholds.connectionPoolUtilization
    ) {
      this.emitAlert({
        type: DatabaseAlertType.CONNECTION_POOL_EXHAUSTED,
        message: `Connection pool utilization is ${this.metrics.connectionPool.utilization}% > ${this.config.alertThresholds.connectionPoolUtilization}% threshold`,
        severity: 'high',
        timestamp: new Date(),
        metadata: {
          utilization: this.metrics.connectionPool.utilization,
          threshold: this.config.alertThresholds.connectionPoolUtilization,
        },
      });
    }

    // Check table sizes
    for (const [tableName, size] of Object.entries(this.metrics.health.tableSizes)) {
      const sizeInMB = size / (1024 * 1024); // Convert to MB
      if (sizeInMB > this.config.alertThresholds.tableSizeThreshold) {
        this.emitAlert({
          type: DatabaseAlertType.TABLE_SIZE_THRESHOLD,
          message: `Table ${tableName} size is ${sizeInMB.toFixed(2)}MB > ${this.config.alertThresholds.tableSizeThreshold}MB threshold`,
          severity: 'medium',
          timestamp: new Date(),
          metadata: {
            tableName,
            size: sizeInMB,
            threshold: this.config.alertThresholds.tableSizeThreshold,
          },
        });
      }
    }

    // Check row counts
    for (const [tableName, count] of Object.entries(this.metrics.health.rowCount)) {
      if (count > this.config.alertThresholds.rowCountThreshold) {
        this.emitAlert({
          type: DatabaseAlertType.ROW_COUNT_THRESHOLD,
          message: `Table ${tableName} has ${count} rows > ${this.config.alertThresholds.rowCountThreshold} threshold`,
          severity: 'medium',
          timestamp: new Date(),
          metadata: {
            tableName,
            rowCount: count,
            threshold: this.config.alertThresholds.rowCountThreshold,
          },
        });
      }
    }

    // Check disk space utilization
    if (this.metrics.diskSpace.utilization > this.config.alertThresholds.diskSpaceUtilization) {
      this.emitAlert({
        type: DatabaseAlertType.DISK_SPACE_LOW,
        message: `Disk space utilization is ${this.metrics.diskSpace.utilization}% > ${this.config.alertThresholds.diskSpaceUtilization}% threshold`,
        severity: 'high',
        timestamp: new Date(),
        metadata: {
          utilization: this.metrics.diskSpace.utilization,
          threshold: this.config.alertThresholds.diskSpaceUtilization,
        },
      });
    }
  }

  /**
   * Get connection pool metrics
   */
  private async getConnectionPoolMetrics(): Promise<DatabaseMetrics['connectionPool']> {
    // Since better-sqlite3 is single-threaded and doesn't have a standard connection pool,
    // we'll return simulated metrics based on what we know about our implementation
    // In a real system, this would interface with a connection pool manager
    const totalConnections = 1; // We only have a single connection in our implementation
    const maxConnections = 10; // Our database.ts has a max of 10 connections

    // This is a simplified calculation since our implementation doesn't track active/idle connections
    const utilization = 0; // Placeholder - would need to track actual usage in the connection pool

    return {
      totalConnections,
      activeConnections: 0, // Placeholder
      idleConnections: 0, // Placeholder
      maxConnections,
      utilization,
    };
  }

  /**
   * Get performance metrics
   */
  private async getPerformanceMetrics(): Promise<DatabaseMetrics['performance']> {
    // For now, return the current metrics
    // In a more advanced implementation, we could query SQLite's performance metrics
    return this.metrics.performance;
  }

  /**
   * Get health metrics (table sizes, row counts)
   */
  private async getHealthMetrics(): Promise<DatabaseMetrics['health']> {
    const db = getDb();

    if (!db) {
      return {
        uptime: process.uptime(),
        tableSizes: {},
        rowCount: {},
      };
    }

    try {
      // Get table names
      const tablesResult = db
        .prepare(
          `
        SELECT name FROM sqlite_master 
        WHERE type='table' 
        AND name NOT LIKE 'sqlite_%'
        AND name NOT LIKE 'index%'
      `,
        )
        .all();

      const tableNames = (tablesResult as { name: string }[]).map((row) => row.name);
      const tableSizes: { [tableName: string]: number } = {};
      const rowCount: { [tableName: string]: number } = {};

      // Get size and row count for each table
      for (const tableName of tableNames) {
        // Get row count
        const countResult: any = db.prepare(`SELECT COUNT(*) as count FROM ${tableName}`).get();
        rowCount[tableName] = countResult.count;

        // For SQLite, getting exact file size for each table is complex
        // We'll approximate by getting the total database file size
        // This would normally be done by querying SQLite's internal stats
        tableSizes[tableName] = 0; // Placeholder - getting individual table sizes in SQLite is complex
      }

      // Actually get the database file size
      const fs = await import('fs/promises');
      const dbPath = process.env.DATABASE_PATH || './database.sqlite';
      const stats = await fs.stat(dbPath);
      const dbFileSize = stats.size;

      // Distribute the database file size proportionally based on row count
      const totalRows = Object.values(rowCount).reduce((sum, count) => sum + count, 0);
      if (totalRows > 0) {
        for (const tableName of tableNames) {
          const proportion = rowCount[tableName] / totalRows;
          tableSizes[tableName] = Math.round(dbFileSize * proportion);
        }
      }

      return {
        uptime: process.uptime(),
        tableSizes,
        rowCount,
      };
    } finally {
      // releaseDb(db);
    }
  }

  /**
   * Get disk space metrics
   */
  private async getDiskSpaceMetrics(): Promise<DatabaseMetrics['diskSpace']> {
    // Note: Node.js doesn't have a direct way to get disk space
    // This is a simplified implementation that won't work on all platforms
    // For a production system, you might need to use a library like 'diskusage'
    try {
      // For now, return placeholder values
      // In a real implementation, this would get actual disk space information
      return {
