      ];

      for (const pattern of maliciousPatterns) {
        const response = await request(app).get('/api/products').query({ orgId: pattern });

        // Should handle gracefully (empty result or error)
        if (response.status === 200) {
          expect(response.body).toHaveLength(0);
        } else {
          expect(response.status).toBeGreaterThanOrEqual(400);
        }
      }
    });

    it('should prevent mass assignment attacks on organizationId', async () => {
      // Attempt to create product with manipulated organizationId in body
      const productServiceA = new ProductService(prisma, orgA.id);

      // Service is scoped to orgA.id, so even if we try to set orgB.id, it should use orgA.id
      const product = await productServiceA.createProduct({
        name: 'Product Mass Assignment',
        sku: 'SKU-MASS-ASSIGN',
        barcode: 'BARCODE-MASS',
        costPrice: 30.0,
      });

      // Verify product was created with correct organizationId
      expect(product.organizationId).toBe(orgA.id);
      expect(product.organizationId).not.toBe(orgB.id);

      // Verify product is only accessible from Org A
      const productsA = await productServiceA.getAllProducts();
      expect(productsA.some((p) => p.id === product.id)).toBe(true);

      const productServiceB = new ProductService(prisma, orgB.id);
      const productsB = await productServiceB.getAllProducts();
      expect(productsB.some((p) => p.id === product.id)).toBe(false);
    });

    it('should prevent mass assignment of organizationId during product creation', async () => {
      const maliciousPayload = {
        name: 'Malicious Product',
        sku: 'MAL-001',
        barcode: 'MAL-1234567890',
        costPrice: 100,
        organizationId: orgB.id, // Attempt to assign to another organization
      };

      const response = await request(app)
        .post('/api/products')
        .set('Authorization', 'Bearer token:tenant1')
        .send(maliciousPayload);

      expect(response.status).toBe(403); // Expect forbidden due to auth middleware ignoring organizationId in payload
      expect(response.body).toHaveProperty('message', expect.stringContaining('Access denied'));
    });

    it('should prevent IDOR (Insecure Direct Object Reference) attacks', async () => {
      // Create products with sequential IDs
      const productServiceA = new ProductService(prisma, orgA.id);
      const productA1 = await productServiceA.createProduct({
        name: 'Product A1',
        sku: 'SKU-IDOR-A1',
        barcode: 'BARCODE-A1',
        costPrice: 15.0,
      });

      const productServiceB = new ProductService(prisma, orgB.id);
      const productB1 = await productServiceB.createProduct({
        name: 'Product B1',
        sku: 'SKU-IDOR-B1',
        barcode: 'BARCODE-B1',
        costPrice: 25.0,
      });

      // Attempt to access Org B's product using Org A's service
      const productFromA = await productServiceA.getProductById(productB1.id);
      expect(productFromA).toBeNull();

      // Verify correct product is accessible
      const productFromB = await productServiceB.getProductById(productB1.id);
      expect(productFromB).not.toBeNull();
      expect(productFromB?.id).toBe(productB1.id);
    });

    it('should prevent enumeration attacks to discover other org IDs', async () => {
      // Attempt to enumerate organization IDs
      const testOrgIds = [
        'org-00000000-0000-0000-0000-000000000001',
        'org-00000000-0000-0000-0000-000000000002',
        'org-00000000-0000-0000-0000-000000000003',
        orgA.id,
        orgB.id,
      ];

      for (const testOrgId of testOrgIds) {
        const response = await request(app).get('/api/products').query({ orgId: testOrgId });

        // All responses should be consistent — no auth header means blocked
        // Should not leak information about which org IDs exist
        expect([200, 400, 403]).toContain(response.status);

        if (response.status === 200) {
          // Should return products only if orgId matches existing org
          if (testOrgId === orgA.id || testOrgId === orgB.id) {
            expect(Array.isArray(response.body)).toBe(true);
          } else {
            expect(response.body).toHaveLength(0);
          }
        }
      }
    });

    it('should handle null/undefined organizationId gracefully', async () => {
      // Test null organizationId — no auth header means 403
      const responseNull = await request(app).get('/api/products').query({ orgId: null });

      expect(responseNull.status).toBe(403);

      // Test undefined organizationId (missing param)
      const responseUndefined = await request(app).get('/api/products');

      expect(responseUndefined.status).toBe(403);

      // Test empty string organizationId
      const responseEmpty = await request(app).get('/api/products').query({ orgId: '' });

      expect(responseEmpty.status).toBe(403);
    });

    it('should reject JWT with invalid signature', async () => {
      // Mock jwt.verify to throw an error (simulating invalid signature)
      mockJwtVerify.mockImplementation(
        (token: string, secret: string, options: any, callback: any) => {
          if (callback) {
            callback(new jwt.JsonWebTokenError('invalid signature'), undefined);
          }
          return undefined;
        },
      );

      const fakeToken = 'invalid.token.here';

      // Attempt to access with invalid JWT - should fail signature validation
      const response = await request(app)
        .get('/api/secure/products')
        .set('Authorization', `Bearer ${fakeToken}`);

      // Real JWT validation returns 403 for invalid signature
      expect(response.status).toBe(403);
      expect(response.body.message).toContain('Invalid token');
    });

    it('should reject JWT with tampered payload', async () => {
      // Mock jwt.verify to throw an error (simulating tampered payload -> invalid signature)
      mockJwtVerify.mockImplementation(
        (token: string, secret: string, options: any, callback: any) => {
          if (callback) {
            callback(new jwt.JsonWebTokenError('invalid signature'), undefined);
          }
          return undefined;
        },
      );

      const tamperedToken = 'tampered.token.here';

      const response = await request(app)
        .get('/api/secure/products')
        .set('Authorization', `Bearer ${tamperedToken}`);

      // Should be rejected due to invalid signature
      expect(response.status).toBe(403);
      expect(response.body.message).toContain('Invalid token');
    });

    it('should accept valid JWT and extract correct organization', async () => {
      // Mock jwt.verify to return a valid decoded token
      mockJwtVerify.mockImplementation(
        (token: string, secret: string, options: any, callback: any) => {
          const decoded = {
            userId: 1,
            organizationId: orgA.id,
            role: 'Manager',
            tierLevel: 'professional',
            exp: Math.floor(Date.now() / 1000) + 3600, // 1 hour from now
          };
          if (callback) {
            callback(null, decoded as any);
          }
          return decoded;
        },
      );

      const fakeToken = 'valid.token.here';

      const response = await request(app)
        .get('/api/secure/products')
        .set('Authorization', `Bearer ${fakeToken}`);

      // Valid token should succeed
      expect(response.status).toBe(200);
      expect(response.body.organizationId).toBe(orgA.id);
      expect(response.body.tierLevel).toBe('professional');
    });

    it('should reject expired JWT', async () => {
      // Mock jwt.verify to throw token expired error
      mockJwtVerify.mockImplementation(
        (token: string, secret: string, options: any, callback: any) => {
          if (callback) {
            callback(new jwt.TokenExpiredError('jwt expired', new Date()), undefined);
          }
          return undefined;
        },
      );

      const expiredToken = 'expired.token.here';

      const response = await request(app)
        .get('/api/secure/products')
        .set('Authorization', `Bearer ${expiredToken}`);

      // Expired token should be rejected (returns 'Invalid token' because
      // the middleware falls back to Clerk auth which also fails)
      expect(response.status).toBe(403);
      expect(response.body.message).toContain('Invalid token');
    });

    it('should reject JWT with missing required fields', async () => {
      // Mock jwt.verify to return a token missing required fields
      mockJwtVerify.mockImplementation(
        (token: string, secret: string, options: any, callback: any) => {
          const decoded = {
            userId: 1,
            role: 'Manager',
            // Missing organizationId and tierLevel
          };
          if (callback) {
            callback(null, decoded as any);
          }
          return decoded;
        },
      );

      const incompleteToken = 'incomplete.token.here';

      const response = await request(app)
        .get('/api/secure/products')
        .set('Authorization', `Bearer ${incompleteToken}`);

      // Missing required fields should be rejected
      expect(response.status).toBe(403);
      expect(response.body.message).toMatch(/Missing tenant context|Malformed token/);
    });

    it('should reject JWT for organization without subscription', async () => {
      // Create org without subscription
      const orphanOrg = await prisma.organization.create({
        data: {
          name: 'Orphan Org',
          slug: 'orphan-org',
          contactEmail: 'orphan@test.com',
        },
      });

      // Mock jwt.verify to return valid token for orphan org
      mockJwtVerify.mockImplementation(
        (token: string, secret: string, options: any, callback: any) => {
          const decoded = {
            userId: 1,
            organizationId: orphanOrg.id,
            role: 'Manager',
            tierLevel: 'professional',
            exp: Math.floor(Date.now() / 1000) + 3600,
          };
          if (callback) {
            callback(null, decoded as any);
          }
          return decoded;
        },
      );

      const token = 'valid.for.orphan';

      const response = await request(app)
        .get('/api/secure/products')
        .set('Authorization', `Bearer ${token}`);

      // Should be rejected due to missing subscription
      expect(response.status).toBe(403);
      expect(response.body.message).toContain('subscription not configured');
    });
  });
});

/**
 * Integration Tests for Multi-Tenant Route Filtering
 *
 * Validates tenant isolation concepts using self-contained mock routes:
 * - Users can only access data from their own organization
 * - Cross-tenant access is properly blocked
 * - Organization validation works in middleware
 * - Feature gates enforce subscription tier limits
 *
 * Uses mock Express app with simulated routes to avoid coupling to real
 * service internals and database connections.
 */

import request from 'supertest';
import express, { Request, Response, NextFunction } from 'express';

interface AuthRequest extends Request {
  userId?: number;
  organizationId?: string | null;
  tierLevel?: string;
  user?: { id: number; role: string };
  userRole?: string;
}

// Simulated tenant data store
const tenantData: Record<string, { products: any[]; inventoryItems: any[]; users: any[] }> = {
  'org-1': {
    products: [{ id: 1, name: 'Product 1', sku: 'SKU001', organizationId: 'org-1' }],
    inventoryItems: [{ id: 1, productId: 1, expiryDate: '2024-12-31', organizationId: 'org-1' }],
    users: [{ id: 1, role: 'Manager', organizationId: 'org-1' }],
  },
  'org-2': {
    products: [{ id: 2, name: 'Product 2', sku: 'SKU002', organizationId: 'org-2' }],
    inventoryItems: [{ id: 2, productId: 2, expiryDate: '2025-06-30', organizationId: 'org-2' }],
    users: [{ id: 2, role: 'Manager', organizationId: 'org-2' }],
  },
};

// Feature tier configuration
const tierFeatures: Record<string, string[]> = {
  starter: ['basic_reports'],
  professional: ['basic_reports', 'advanced_analytics'],
  premium: ['basic_reports', 'advanced_analytics', 'custom_exports'],
};

describe('Multi-Tenant Route Filtering Integration Tests', () => {
  let testApp: express.Express;

  const org1 = { id: 'org-1', name: 'Pharmacy A' };
  const org2 = { id: 'org-2', name: 'Pharmacy B' };
  const user1 = { id: 1, organizationId: org1.id };
  const user2 = { id: 2, organizationId: org2.id };

  // Configurable auth middleware
  let authConfig = { userId: 1, organizationId: 'org-1', tierLevel: 'starter', role: 'Manager' };

  const authMiddleware = (req: AuthRequest, _res: Response, next: NextFunction) => {
    req.userId = authConfig.userId;
    req.organizationId = authConfig.organizationId;
    req.tierLevel = authConfig.tierLevel;
    req.user = { id: authConfig.userId, role: authConfig.role };
    req.userRole = authConfig.role;
    next();
  };

  const requireFeature =
    (featureKey: string) => (req: AuthRequest, res: Response, next: NextFunction) => {
      const tier = req.tierLevel || 'starter';
      const features = tierFeatures[tier] || [];
      if (!features.includes(featureKey)) {
        return res.status(403).json({
          error: 'Feature not available',
          message: 'Please upgrade your plan to access this feature',
        });
      }
      next();
    };

  const checkUsageLimit = () => (_req: AuthRequest, _res: Response, next: NextFunction) => next();

  beforeEach(() => {
    authConfig = { userId: 1, organizationId: 'org-1', tierLevel: 'starter', role: 'Manager' };

    testApp = express();
    testApp.use(express.json());
    testApp.use(authMiddleware);

    // Product routes — scoped by organizationId
    testApp.get('/api/products', (req: AuthRequest, res: Response) => {
      const orgData = tenantData[req.organizationId || ''];
      res.json(orgData?.products || []);
    });
    testApp.post('/api/products', checkUsageLimit(), (req: AuthRequest, res: Response) => {
      res.status(201).json({ ...req.body, organizationId: req.organizationId });
    });

    // Inventory routes — scoped by organizationId
    testApp.get('/api/inventory-items', (req: AuthRequest, res: Response) => {
      const orgData = tenantData[req.organizationId || ''];
      res.json(orgData?.inventoryItems || []);
    });
    testApp.post('/api/inventory-items', checkUsageLimit(), (req: AuthRequest, res: Response) => {
      res.status(200).json({ ...req.body, organizationId: req.organizationId });
    });

    // User routes — scoped by organizationId
    testApp.get('/api/users', (req: AuthRequest, res: Response) => {
      const orgData = tenantData[req.organizationId || ''];
      res.json(orgData?.users || []);
    });
    testApp.post('/api/users', checkUsageLimit(), (req: AuthRequest, res: Response) => {
      res.status(200).json({ ...req.body, organizationId: req.organizationId });
    });

    // Storage quota routes — validates userId ownership
    testApp.get('/api/storage-quota/:userId', (req: AuthRequest, res: Response) => {
      const paramUserId = parseInt(req.params.userId, 10);
      if (!req.userId) return res.status(401).json({ error: 'Unauthorized' });
      if (req.userId !== paramUserId) {
        return res
          .status(403)
          .json({ error: 'Forbidden', message: 'You can only access your own storage quota' });
      }
      res.json({ used: 1024, limit: 10485760, percentageUsed: 0.01, tier: req.tierLevel });
    });

    // Upload routes
    testApp.post('/api/upload/initiate', checkUsageLimit(), (req: AuthRequest, res: Response) => {
      res.status(200).json({ uploadId: 'test-upload', organizationId: req.organizationId });
    });

    // Analytics routes — feature-gated
    testApp.get(
      '/api/reports/analytics',
      requireFeature('advanced_analytics'),
      (req: AuthRequest, res: Response) => {
        res.json({ data: [], organizationId: req.organizationId });
      },
    );
  });

  describe('Product Routes Tenant Filtering', () => {
    it('should allow user to access products from their organization', async () => {
      authConfig = { ...authConfig, userId: user1.id, organizationId: org1.id };

      const response = await request(testApp).get('/api/products').expect(200);

      expect(response.body).toHaveLength(1);
      expect(response.body[0].organizationId).toBe(org1.id);
    });

    it('should prevent user from accessing products from another organization', async () => {
      authConfig = { ...authConfig, userId: user2.id, organizationId: org2.id };

      const response = await request(testApp).get('/api/products').expect(200);

      expect(response.body).toHaveLength(1);
      expect(response.body[0].organizationId).toBe(org2.id);
      // Org2 user cannot see org1 products
      expect(response.body.find((p: any) => p.organizationId === org1.id)).toBeUndefined();
    });
  });

  describe('Inventory Routes Tenant Filtering', () => {
    it('should enforce SKU limits based on subscription tier', async () => {
      authConfig = {
        ...authConfig,
        userId: user1.id,
        organizationId: org1.id,
        tierLevel: 'starter',
      };

      const response = await request(testApp)
        .post('/api/inventory-items')
        .send({ productId: 1, expiryDate: '2025-12-31', locationId: 1 })
        .expect(200);

      expect(response.body).toBeDefined();
      expect(response.body.organizationId).toBe(org1.id);
    });

    it('should filter inventory items by organization', async () => {
      authConfig = { ...authConfig, userId: user1.id, organizationId: org1.id };

      const response = await request(testApp).get('/api/inventory-items').expect(200);

      expect(response.body).toHaveLength(1);
      expect(response.body[0].organizationId).toBe(org1.id);
    });
  });

  describe('User Routes Tenant Filtering', () => {
    it('should enforce user limits based on subscription tier', async () => {
      authConfig = {
        ...authConfig,
        userId: user1.id,
        organizationId: org1.id,
        tierLevel: 'starter',
      };

      const response = await request(testApp)
        .post('/api/users')
        .send({ pin: '5678', role: 'Employee' })
        .expect(200);

      expect(response.body).toBeDefined();
      expect(response.body.organizationId).toBe(org1.id);
    });

    it('should prevent cross-tenant user access', async () => {
      authConfig = { ...authConfig, userId: user1.id, organizationId: org1.id };

      const response = await request(testApp).get('/api/users').expect(200);

      expect(response.body).toHaveLength(1);
      expect(response.body[0].organizationId).toBe(org1.id);
      // Should not return org2 users
      expect(response.body.find((u: any) => u.organizationId === org2.id)).toBeUndefined();
    });
  });

  describe('Storage Quota Routes Tenant Filtering', () => {
    it('should validate organization ownership for storage quota access', async () => {
      authConfig = { ...authConfig, userId: user1.id, organizationId: org1.id };

      const response = await request(testApp).get('/api/storage-quota/1').expect(200);

      expect(response.body).toBeDefined();
      expect(response.body.used).toBeDefined();
    });

    it('should reject access to storage quota of different organization user', async () => {
      authConfig = { ...authConfig, userId: user1.id, organizationId: org1.id };

      const response = await request(testApp).get('/api/storage-quota/2').expect(403);

      expect(response.body.error).toBe('Forbidden');
      expect(response.body.message).toContain('own storage quota');
    });
  });

  describe('Upload Routes Tenant Filtering', () => {
    it('should enforce storage limits on upload operations', async () => {
      authConfig = {
        ...authConfig,
        userId: user1.id,
        organizationId: org1.id,
        tierLevel: 'starter',
      };

      const response = await request(testApp)
        .post('/api/upload/initiate')
        .send({ filename: 'test.csv', fileSize: 1024, contentType: 'text/csv' })
        .expect(200);

      expect(response.body).toBeDefined();
      expect(response.body.organizationId).toBe(org1.id);
    });

    it('should apply tenant context to all upload operations', async () => {
      authConfig = { ...authConfig, userId: user1.id, organizationId: org1.id };

      const response = await request(testApp)
        .post('/api/upload/initiate')
        .send({ filename: 'test.csv', fileSize: 1024, contentType: 'text/csv' })
        .expect(200);

      expect(response.body).toBeDefined();
      expect(response.body.organizationId).toBe(org1.id);
    });
  });

  describe('Analytics Route Feature Gating', () => {
    it('should allow premium tier access to analytics', async () => {
      authConfig = {
        ...authConfig,
        userId: user1.id,
        organizationId: org1.id,
        tierLevel: 'premium',
      };

      const response = await request(testApp).get('/api/reports/analytics').expect(200);

      expect(response.body).toBeDefined();
      expect(response.body.organizationId).toBe(org1.id);
