const makeResponse = () => {
  const res = {
    status: jest.fn().mockReturnThis(),
    json: jest.fn().mockReturnThis(),
  } as any;

  return res;
};

const makeRequest = (overrides?: Partial<AuthRequest>): AuthRequest =>
  ({
    headers: {},
    ip: '127.0.0.1',
    get: jest.fn((header: string) => (header === 'User-Agent' ? 'test-agent' : undefined)),
    path: '/test',
    method: 'GET',
    ...overrides,
  }) as AuthRequest;

const testInvalidTokenScenario = async (
  errorMessage: string,
  nextFn: jest.Mock,
  expectTracking = true,
): Promise<void> => {
  const req = makeRequest({ headers: { authorization: 'Bearer invalid-token' } });
  const res = makeResponse();

  (jwt.verify as jest.Mock).mockImplementation(() => {
    throw new Error(errorMessage);
  });

  await authenticateToken(req, res, nextFn);

  expect(res.status).toHaveBeenCalledWith(403);
  expect(res.json).toHaveBeenCalledWith({ message: 'Access denied: Invalid token' });
  if (expectTracking) {
    expect(trackEvent).toHaveBeenCalledWith(
      expect.objectContaining({ eventAction: 'invalid_token_attempt' }),
    );
  }
  expect(nextFn).not.toHaveBeenCalled();
};

describe('auth middleware', () => {
  const next = jest.fn();

  beforeEach(() => {
    jest.clearAllMocks();
    process.env.NODE_ENV = 'test';
    process.env.TEST_AUTH_BYPASS = 'false';
    process.env.JWT_SECRET = 'test_secret';
    delete process.env.JWT_SECRET_OLD;
    mockPrisma = {
      subscriptionTier: {
        findFirst: jest.fn(),
      },
    };
    mockIsAccessActive = jest.fn();
  });

  describe('authenticateToken', () => {
    it('rejects when no token is provided', () => {
      const req = makeRequest();
      const res = makeResponse();

      authenticateToken(req, res, next);

      expect(res.status).toHaveBeenCalledWith(401);
      expect(res.json).toHaveBeenCalledWith({ message: 'Access denied: No token provided' });
      expect(trackEvent).toHaveBeenCalledWith(
        expect.objectContaining({ eventAction: 'unauthorized_access_attempt' }),
      );
      expect(next).not.toHaveBeenCalled();
    });

    it('rejects invalid token when verification fails', async () => {
      await testInvalidTokenScenario('invalid', next);
    });

    it('rejects invalid token when rotation secret also fails', async () => {
      await testInvalidTokenScenario('invalid signature', next, false);
    });

    it('handles malformed token header gracefully', () => {
      const req = makeRequest({ headers: { authorization: 'invalid-format' } });
      const res = makeResponse();

      authenticateToken(req, res, next);

      expect(res.status).toHaveBeenCalledWith(401);
      expect(res.json).toHaveBeenCalledWith({
        message: 'Access denied: No token provided',
      });
      expect(next).not.toHaveBeenCalled();
    });

    it('rejects when decoded payload is invalid', async () => {
      const req = makeRequest({ headers: { authorization: 'Bearer token' } });
      const res = makeResponse();

      (jwt.verify as jest.Mock).mockReturnValue('not-a-payload');

      await authenticateToken(req, res, next);

      expect(res.status).toHaveBeenCalledWith(403);
      expect(res.json).toHaveBeenCalledWith({ message: 'Access denied: Invalid token payload' });
      expect(next).not.toHaveBeenCalled();
    });

    it('rejects when token is expired', async () => {
      const req = makeRequest({ headers: { authorization: 'Bearer expired-token' } });
      const res = makeResponse();

      (jwt.verify as jest.Mock).mockReturnValue({
        userId: 1,
        role: 'Admin',
        organizationId: 'org-1',
        tierLevel: 'starter',
        exp: Math.floor(Date.now() / 1000) - 3600, // Expired 1 hour ago
      });

      await authenticateToken(req, res, next);

      expect(res.status).toHaveBeenCalledWith(403);
      expect(res.json).toHaveBeenCalledWith({ message: 'Access denied: Token has expired' });
      expect(next).not.toHaveBeenCalled();
    });

    it('accepts valid token and sets user fields', async () => {
      const req = makeRequest({ headers: { authorization: 'Bearer token' } });
      const res = makeResponse();

      (jwt.verify as jest.Mock).mockReturnValue({
        userId: 7,
        role: 'Manager',
        organizationId: 'org-1',
        tierLevel: 'professional',
        exp: Math.floor(Date.now() / 1000) + 300,
      });

      (mockPrisma.subscriptionTier.findFirst as jest.Mock).mockResolvedValue({
        id: 1,
        organizationId: 'org-1',
        tierLevel: 'professional',
        status: SubscriptionStatus.ACTIVE,
        billingCycle: 'monthly',
        createdAt: new Date(),
        updatedAt: new Date(),
      });

      mockIsAccessActive.mockResolvedValue(true);

      await authenticateToken(req, res, next);

      expect(req.userId).toBe(7);
      expect(req.userRole).toBe('Manager');
      expect(req.user).toEqual({
        id: 7,
        role: 'Manager',
        organizationId: 'org-1',
        tierLevel: 'professional',
      });
      expect(trackEvent).toHaveBeenCalledWith(
        expect.objectContaining({ eventAction: 'protected_route_access' }),
      );
      expect(next).toHaveBeenCalled();
    });

    it('allows access when subscription is canceled but Stripe still active', async () => {
      const req = makeRequest({ headers: { authorization: 'Bearer token' } });
      const res = makeResponse();

      (jwt.verify as jest.Mock).mockReturnValue({
        userId: 7,
        role: 'Manager',
        organizationId: 'org-1',
        tierLevel: 'professional',
        exp: Math.floor(Date.now() / 1000) + 300,
      });

      (mockPrisma.subscriptionTier.findFirst as jest.Mock).mockResolvedValue({
        id: 1,
        organizationId: 'org-1',
        tierLevel: 'professional',
        status: SubscriptionStatus.CANCELED,
        billingCycle: 'monthly',
        createdAt: new Date(),
        updatedAt: new Date(),
      });

      mockIsAccessActive.mockResolvedValue(true);

      await authenticateToken(req, res, next);

      expect(next).toHaveBeenCalled();
      expect(res.status).not.toHaveBeenCalledWith(403);
    });

    it('rejects access when subscription is canceled and period ended', async () => {
      const req = makeRequest({ headers: { authorization: 'Bearer token' } });
      const res = makeResponse();

      (jwt.verify as jest.Mock).mockReturnValue({
        userId: 7,
        role: 'Manager',
        organizationId: 'org-1',
        tierLevel: 'professional',
        exp: Math.floor(Date.now() / 1000) + 300,
      });

      (mockPrisma.subscriptionTier.findFirst as jest.Mock).mockResolvedValue({
        id: 1,
        organizationId: 'org-1',
        tierLevel: 'professional',
        status: SubscriptionStatus.CANCELED,
        billingCycle: 'monthly',
        createdAt: new Date(),
        updatedAt: new Date(),
      });

      // Clear the cache module state or use a different org ID to avoid cache hits
      req.user = undefined;
      (jwt.verify as jest.Mock).mockReturnValue({
        userId: 7,
        role: 'Manager',
        organizationId: 'org-uncached',
        tierLevel: 'professional',
        exp: Math.floor(Date.now() / 1000) + 300,
      });

      mockIsAccessActive.mockResolvedValue(false);

      await authenticateToken(req, res, next);

      expect(res.status).toHaveBeenCalledWith(403);
      expect(res.json).toHaveBeenCalledWith({
        message:
          'Access denied: Organization subscription has been canceled. Please contact support.',
      });
      expect(next).not.toHaveBeenCalled();
    });
  });

  describe('requireManager', () => {
    it('rejects non-manager roles', () => {
      const req = makeRequest({ userId: 1, userRole: 'Staff' });
      const res = makeResponse();

      requireManager(req, res, next);

      expect(res.status).toHaveBeenCalledWith(403);
      expect(res.json).toHaveBeenCalledWith({ message: 'Access denied: Manager role required' });
      expect(trackEvent).toHaveBeenCalledWith(
        expect.objectContaining({ eventAction: 'manager_access_denied' }),
      );
      expect(next).not.toHaveBeenCalled();
    });

    it('allows manager role', () => {
      const req = makeRequest({ userId: 1, userRole: 'Manager' });
      const res = makeResponse();

      requireManager(req, res, next);

      expect(next).toHaveBeenCalled();
    });

    it('allows admin role', () => {
      const req = makeRequest({ userId: 1, userRole: 'admin' });
      const res = makeResponse();

      requireManager(req, res, next);

      expect(next).toHaveBeenCalled();
    });
  });
});

import { PrismaClient } from '@prisma/client';
import jwt from 'jsonwebtoken';
import bcrypt from 'bcrypt';
import crypto from 'crypto';
import { AuthService } from '../../services/auth.service';
import { AuthenticationError, InternalError } from '../../errors';
import { SubscriptionStatus } from '../../types/subscription';

// Mock the jsonwebtoken module
jest.mock('jsonwebtoken', () => ({
  sign: jest.fn(),
  verify: jest.fn(),
}));

// Mock the bcrypt module
jest.mock('bcrypt', () => ({
  hash: jest.fn(),
  compare: jest.fn(),
}));

// Mock crypto for refresh tokens
jest.mock('crypto', () => ({
  randomBytes: jest.fn(() => ({
    toString: jest.fn(() => 'mock_refresh_token_hex'),
  })),
}));

describe('AuthService', () => {
  let authService: AuthService;
  let prisma: PrismaClient;

  beforeEach(() => {
    prisma = {
      user: {
        findMany: jest.fn(),
      },
      subscriptionTier: {
        findFirst: jest.fn(),
      },
      refreshToken: {
        create: jest.fn(),
        findUnique: jest.fn(),
        update: jest.fn(),
        delete: jest.fn(),
        deleteMany: jest.fn(),
      },
    } as unknown as PrismaClient;

    authService = new AuthService(prisma);
    (jwt.sign as jest.Mock).mockReturnValue('mock_jwt_token');
    (jwt.verify as jest.Mock).mockReturnValue({
      userId: 1,
      role: 'Manager',
      organizationId: 'org-1',
      tierLevel: 'professional',
    });
    (bcrypt.compare as jest.Mock).mockResolvedValue(true);
    (bcrypt.hash as jest.Mock).mockResolvedValue('hashed_pin');
    process.env.JWT_SECRET = 'test_secret';
  });

  afterEach(() => {
    jest.clearAllMocks();
  });

  describe('validatePin', () => {
    it('rejects non-digit pins and invalid lengths', () => {
      expect(authService.validatePin('12ab')).toEqual({
        isValid: false,
        message: 'PIN must be 4-6 digits long and contain only numbers',
      });
      expect(authService.validatePin('123')).toEqual({
        isValid: false,
        message: 'PIN must be 4-6 digits long and contain only numbers',
      });
    });

    it('rejects predictable patterns', () => {
      expect(authService.validatePin('1234').isValid).toBe(false);
      expect(authService.validatePin('1111').isValid).toBe(false);
    });

    it('accepts a valid pin', () => {
      expect(authService.validatePin('5624')).toEqual({ isValid: true });
    });
  });

  describe('hashPin', () => {
    it('hashes PIN with bcrypt', async () => {
      const result = await authService.hashPin('5624');

      expect(bcrypt.hash).toHaveBeenCalledWith('5624', 10);
      expect(result).toBe('hashed_pin');
    });
  });

  describe('verifyPin', () => {
    it('verifies PIN with bcrypt', async () => {
      (bcrypt.compare as jest.Mock).mockResolvedValue(true);

      const result = await authService.verifyPin('5624', 'hashed_pin');

      expect(bcrypt.compare).toHaveBeenCalledWith('5624', 'hashed_pin');
      expect(result).toBe(true);
    });
  });

  describe('login', () => {
    it('always throws AuthenticationError since PIN auth is disabled (Clerk is used)', async () => {
      // PIN auth removed — isValidPin is hardcoded to false in login()
      (prisma.user.findMany as jest.Mock).mockResolvedValue([
        { id: 1, role: 'Manager', organizationId: 'org-1' },
      ]);

      await expect(authService.login('5624')).rejects.toBeInstanceOf(AuthenticationError);
      expect(jwt.sign).not.toHaveBeenCalled();
    });

    it('throws AuthenticationError when no users exist', async () => {
      (prisma.user.findMany as jest.Mock).mockResolvedValue([]);

      await expect(authService.login('5624')).rejects.toBeInstanceOf(AuthenticationError);
    });

    it('throws InternalError on unexpected failures', async () => {
      (prisma.user.findMany as jest.Mock).mockRejectedValue(new Error('DB failure'));

      await expect(authService.login('5624')).rejects.toBeInstanceOf(InternalError);
    });
  });

  describe('generateTokens', () => {
    it('generates access and refresh tokens for a user', async () => {
      (prisma.refreshToken.create as jest.Mock).mockResolvedValue({
        id: 1,
        userId: 1,
        token: 'mock_refresh_token_hex',
        expiresAt: expect.any(Date),
      });

      const tokens = await authService.generateTokens(1, 'Manager');

      expect(tokens.accessToken).toBe('mock_jwt_token');
      expect(tokens.refreshToken).toBe('mock_refresh_token_hex');
      expect(prisma.refreshToken.create).toHaveBeenCalledWith({
        data: {
          userId: 1,
          token: 'mock_refresh_token_hex',
          expiresAt: expect.any(Date),
        },
      });
    });

    it('throws InternalError on database failure', async () => {
      (prisma.refreshToken.create as jest.Mock).mockRejectedValue(new Error('DB failure'));

      await expect(authService.generateTokens(1, 'Manager')).rejects.toBeInstanceOf(InternalError);
    });
  });

  describe('verifyToken', () => {
    it('successfully verifies and decodes a valid token', () => {
      (jwt.verify as jest.Mock).mockReturnValue({ userId: 7, role: 'Staff', exp: 1234567890 });

      const payload = authService.verifyToken('valid_token');

      expect(payload.userId).toBe(7);
      expect(payload.role).toBe('Staff');
      expect(jwt.verify).toHaveBeenCalledWith('valid_token', 'test_secret');
    });

    it('throws AuthenticationError for expired token', () => {
      (jwt.verify as jest.Mock).mockImplementation(() => {
        const error: any = new Error('jwt expired');
        error.name = 'TokenExpiredError';
        throw error;
      });

      expect(() => authService.verifyToken('expired_token')).toThrow(AuthenticationError);
    });

    it('throws AuthenticationError for tampered/invalid signature', () => {
      (jwt.verify as jest.Mock).mockImplementation(() => {
        const error: any = new Error('invalid signature');
        error.name = 'JsonWebTokenError';
        throw error;
      });

      expect(() => authService.verifyToken('tampered_token')).toThrow(AuthenticationError);
    });
  });

  describe('refreshAccessToken', () => {
    it('issues new access token with valid refresh token', async () => {
      const futureDate = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000); // 7 days from now
      (prisma.refreshToken.findUnique as jest.Mock).mockResolvedValue({
        id: 1,
        userId: 5,
        token: 'valid_refresh_token',
        expiresAt: futureDate,
        revokedAt: null,
        user: { id: 5, role: 'Staff', pin: 'hashed', createdAt: new Date(), updatedAt: new Date() },
      });

      const newAccessToken = await authService.refreshAccessToken('valid_refresh_token');

      expect(newAccessToken).toBe('mock_jwt_token');
      expect(jwt.sign).toHaveBeenCalledWith({ userId: 5, role: 'Staff' }, 'test_secret', {
        expiresIn: '1h',
      });
    });

    it('throws AuthenticationError for non-existent refresh token', async () => {
      (prisma.refreshToken.findUnique as jest.Mock).mockResolvedValue(null);

      await expect(authService.refreshAccessToken('invalid_token')).rejects.toBeInstanceOf(
        AuthenticationError,
      );
    });

    it('throws AuthenticationError and deletes expired refresh token', async () => {
      const pastDate = new Date(Date.now() - 1000); // Expired
      (prisma.refreshToken.findUnique as jest.Mock).mockResolvedValue({
        id: 1,
        userId: 5,
        token: 'expired_refresh_token',
        expiresAt: pastDate,
        revokedAt: null,
        user: { id: 5, role: 'Staff', pin: 'hashed', createdAt: new Date(), updatedAt: new Date() },
      });

      await expect(authService.refreshAccessToken('expired_refresh_token')).rejects.toBeInstanceOf(
        AuthenticationError,
      );
      expect(prisma.refreshToken.delete).toHaveBeenCalledWith({ where: { id: 1 } });
    });

    it('throws AuthenticationError for revoked refresh token', async () => {
      const futureDate = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000);
      (prisma.refreshToken.findUnique as jest.Mock).mockResolvedValue({
        id: 1,
        userId: 5,
        token: 'revoked_token',
        expiresAt: futureDate,
        revokedAt: new Date(), // Token was revoked
        user: { id: 5, role: 'Staff', pin: 'hashed', createdAt: new Date(), updatedAt: new Date() },
      });

      await expect(authService.refreshAccessToken('revoked_token')).rejects.toBeInstanceOf(
        AuthenticationError,
      );
    });
  });

  describe('revokeRefreshToken', () => {
    it('successfully revokes a refresh token', async () => {
      (prisma.refreshToken.findUnique as jest.Mock).mockResolvedValue({
        id: 1,
        userId: 5,
        token: 'token_to_revoke',
        expiresAt: new Date(),
      });
      (prisma.refreshToken.update as jest.Mock).mockResolvedValue({});

      await authService.revokeRefreshToken('token_to_revoke');

      expect(prisma.refreshToken.update).toHaveBeenCalledWith({
        where: { id: 1 },
        data: { revokedAt: expect.any(Date) },
      });
    });

    it('silently succeeds when token does not exist', async () => {
      (prisma.refreshToken.findUnique as jest.Mock).mockResolvedValue(null);

      await expect(authService.revokeRefreshToken('non_existent_token')).resolves.toBeUndefined();
      expect(prisma.refreshToken.update).not.toHaveBeenCalled();
    });

    it('throws InternalError on database failure', async () => {
      (prisma.refreshToken.findUnique as jest.Mock).mockResolvedValue({ id: 1 });
      (prisma.refreshToken.update as jest.Mock).mockRejectedValue(new Error('DB failure'));

      await expect(authService.revokeRefreshToken('token')).rejects.toBeInstanceOf(InternalError);
    });
  });

  describe('cleanupExpiredTokens', () => {
    it('deletes expired tokens and returns count', async () => {
      (prisma.refreshToken.deleteMany as jest.Mock).mockResolvedValue({ count: 5 });

      const count = await authService.cleanupExpiredTokens();

      expect(count).toBe(5);
      expect(prisma.refreshToken.deleteMany).toHaveBeenCalledWith({
        where: { expiresAt: { lt: expect.any(Date) } },
      });
    });

    it('returns 0 on database failure', async () => {
      (prisma.refreshToken.deleteMany as jest.Mock).mockRejectedValue(new Error('DB failure'));

      const count = await authService.cleanupExpiredTokens();

      expect(count).toBe(0);
    });
  });
});

/**
 * Unit Tests for Environment Configuration
 */

const originalEnv = process.env;

const loadEnvModule = () => {
  jest.resetModules();
  // Mock dotenv to prevent file loading interference
  jest.doMock('dotenv', () => ({
    config: jest.fn(),
  }));
  return require('../../config/environment') as typeof import('../../config/environment');
};

describe('EnvironmentConfig', () => {
  beforeEach(() => {
    process.env = { ...originalEnv };
  });

  const mockExit = jest.spyOn(process, 'exit').mockImplementation((() => {
    throw new Error('process.exit called');
  }) as any);
  const mockConsoleError = jest.spyOn(console, 'error').mockImplementation(() => {});

  afterAll(() => {
    process.env = originalEnv;
    mockExit.mockRestore();
    mockConsoleError.mockRestore();
  });

  it('defaults to development when NODE_ENV is missing', () => {
    delete process.env.NODE_ENV;
    delete process.env.PORT;
    process.env.JWT_SECRET = 'dev-secret';

    const envModule = loadEnvModule();

    expect(envModule.envConfig.NODE_ENV).toBe('development');
    expect(envModule.envConfig.PORT).toBe(3001);
    expect(envModule.envConfig.JWT_SECRET).toBe('dev-secret');
  });

  it('uses provided JWT_SECRET when NODE_ENV is test', () => {
    process.env.NODE_ENV = 'test';
    delete process.env.PORT;
    process.env.JWT_SECRET = 'test_secret';

    const envModule = loadEnvModule();

    expect(envModule.envConfig.NODE_ENV).toBe('test');
    expect(envModule.envConfig.PORT).toBe(3001);
    expect(envModule.envConfig.JWT_SECRET).toBe('test_secret');
  });

  it('throws when development is missing JWT_SECRET', () => {
    process.env.NODE_ENV = 'development';
    process.env.PORT = '3001';
    delete process.env.JWT_SECRET;

    expect(() => loadEnvModule()).toThrow('process.exit called');
    expect(mockConsoleError).toHaveBeenCalledWith('JWT_SECRET environment variable is empty');
  });

  it('throws when production is missing JWT_SECRET', () => {
    process.env.NODE_ENV = 'production';
    process.env.PORT = '3001';
    delete process.env.JWT_SECRET;

    expect(() => loadEnvModule()).toThrow('process.exit called');
    expect(mockConsoleError).toHaveBeenCalledWith('JWT_SECRET environment variable is empty');
  });

  it('allows worker config injection', () => {
    const envModule = loadEnvModule();

    envModule.setWorkerConfig({
      NODE_ENV: 'production',
      PORT: '8080',
      JWT_SECRET: 'worker-secret',
    });

    expect(envModule.envConfig.NODE_ENV).toBe('production');
    expect(envModule.envConfig.PORT).toBe(8080);
    expect(envModule.envConfig.JWT_SECRET).toBe('worker-secret');
  });
});

