    });

    it("should return 'Markdown 1' for dates between 15 and 30 days from now", () => {
      const date = new Date();
      date.setDate(date.getDate() + 30);
      const expiryDate = date.toISOString().split('T')[0];
      expect(inventoryService.calculateMarkdownStatusSync(expiryDate)).toBe('Markdown 1');
    });

    it('should return "Normal" for dates more than 30 days from now', () => {
      const date = new Date();
      date.setDate(date.getDate() + 31);
      const expiryDate = date.toISOString().split('T')[0];
      expect(inventoryService.calculateMarkdownStatusSync(expiryDate)).toBe('Normal');
    });
  });
});

import { PrismaClient } from '@prisma/client';
import { OrganizationInviteService } from '../../services/organization-invite.service';
import { ConflictError, NotFoundError, PaymentRequiredError, ValidationError } from '../../errors';

const now = new Date('2026-02-17T00:00:00.000Z');

describe('OrganizationInviteService', () => {
  let service: OrganizationInviteService;
  let mockPrisma: any;

  beforeEach(() => {
    mockPrisma = {
