        findFirst: jest.fn(),
      },
      user: {
        count: jest.fn(),
        findFirst: jest.fn(),
        create: jest.fn(),
      },
      organizationInvite: {
        count: jest.fn(),
        findFirst: jest.fn(),
        findMany: jest.fn(),
        create: jest.fn(),
        update: jest.fn(),
      },
      $transaction: jest.fn(async (arg: any) => {
        if (Array.isArray(arg)) {
          return Promise.all(arg);
        }
        return arg(mockPrisma);
      }),
    };

    service = new OrganizationInviteService(mockPrisma as unknown as PrismaClient, () => now);
  });

  afterEach(() => {
    jest.clearAllMocks();
  });

