      const notFoundError = { code: 'P2025' };
      (prisma.user.delete as jest.Mock).mockRejectedValue(notFoundError);

      const result = await service.deleteUser(999);

      expect(result).toBe(false);
    });
  });
});

import Stripe from 'stripe';
import { PrismaClient } from '@prisma/client';
import { WebhookService } from '../../services/webhook.service';
import { EmailService } from '../../services/email.service';
import { SubscriptionStatus } from '../../types/subscription';
import { NotFoundError } from '../../errors';

jest.mock('@sendgrid/mail', () => ({
  setApiKey: jest.fn(),
  send: jest.fn(),
}));

jest.mock('../../database/database-factory');

type MockPrisma = {
  [key: string]: any;
  $transaction: jest.Mock;
};

describe('WebhookService', () => {
  let prisma: MockPrisma;
  let emailService: jest.Mocked<EmailService>;
  let service: WebhookService;
  let mockStripe: jest.Mocked<Stripe>;

  const organizationId = 'org-123';
  const customerId = 'cus_test123';

  beforeEach(() => {
    process.env.STRIPE_SECRET_KEY = 'sk_test_123';
    process.env.STRIPE_WEBHOOK_SECRET = 'whsec_test_123';

    prisma = {
      processedWebhookEvent: {
        findUnique: jest.fn(),
        create: jest.fn(),
      },
      organization: {
        findUnique: jest.fn(),
      },
      subscriptionTier: {
        create: jest.fn(),
        updateMany: jest.fn(),
        findFirst: jest.fn(),
      },
      organizationUsage: {
        upsert: jest.fn(),
        update: jest.fn(),
        findUnique: jest.fn(),
      },
      auditLog: {
        create: jest.fn(),
      },
      $transaction: jest.fn((callback) => callback(prisma)),
    };

    emailService = {
      sendTrialReminderEmail: jest.fn(),
      sendDunningEmail: jest.fn(),
      sendDowngradeWarningEmail: jest.fn(),
    } as unknown as jest.Mocked<EmailService>;

    service = new WebhookService(prisma as unknown as PrismaClient, undefined, emailService);

    mockStripe = {
      customers: {
        retrieve: jest.fn(),
      },
    } as unknown as jest.Mocked<Stripe>;

    (service as unknown as { stripe: Stripe }).stripe = mockStripe;

    (mockStripe.customers.retrieve as jest.Mock).mockResolvedValue({
      id: customerId,
      deleted: false,
      metadata: { organizationId },
    });

    prisma.organization.findUnique.mockResolvedValue({
      id: organizationId,
      name: 'Test Org',
    });
  });

  afterEach(() => {
    jest.clearAllMocks();
  });

  describe('idempotency helpers', () => {
    it('returns true when event has not been processed', async () => {
      prisma.processedWebhookEvent.findUnique.mockResolvedValue(null);

      const result = await service.isNewEvent('evt_new');

      expect(result).toBe(true);
      expect(prisma.processedWebhookEvent.findUnique).toHaveBeenCalledWith({
        where: { id: 'evt_new' },
      });
    });

    it('returns false when event has already been processed', async () => {
      prisma.processedWebhookEvent.findUnique.mockResolvedValue({ id: 'evt_existing' });

      const result = await service.isNewEvent('evt_existing');

      expect(result).toBe(false);
    });

    it('swallows unique constraint errors when marking processed', async () => {
      const error = { code: 'P2002' };
      prisma.processedWebhookEvent.create.mockRejectedValue(error);

      await expect(service.markEventProcessed('evt_dup', 'invoice.payment_failed')).resolves.toBe(
        undefined,
      );
    });
  });

  describe('handler behaviors', () => {
    it('handles subscription created', async () => {
      prisma.subscriptionTier.create.mockResolvedValue({ id: 1 });
      prisma.organizationUsage.upsert.mockResolvedValue({ id: 1 });
      prisma.auditLog.create.mockResolvedValue({ id: 1 });

      const subscription = {
        id: 'sub_created',
        customer: customerId,
        status: 'active',
        items: {
          data: [
            {
              price: {
                recurring: { interval: 'month' },
                metadata: { tier: 'starter' },
              },
            },
          ],
        },
        trial_end: null,
      } as unknown as Stripe.Subscription;

      await (service as any).handleSubscriptionCreated(subscription);

      expect(prisma.subscriptionTier.create).toHaveBeenCalled();
      expect(prisma.organizationUsage.upsert).toHaveBeenCalled();
      expect(prisma.auditLog.create).toHaveBeenCalledWith({
        data: expect.objectContaining({
          organizationId,
          action: 'subscription_created',
        }),
      });
    });

    it('handles subscription updated and sends downgrade warning', async () => {
      prisma.subscriptionTier.findFirst.mockResolvedValue({
        tierLevel: 'professional',
      });
      prisma.organizationUsage.findUnique.mockResolvedValue({
        totalSkus: 9999,
      });

      const subscription = {
        id: 'sub_updated',
        customer: customerId,
        status: 'active',
        items: {
          data: [
            {
              price: {
                metadata: { tier: 'starter' },
              },
            },
          ],
        },
        trial_end: null,
        current_period_end: Math.floor(Date.now() / 1000) + 1000,
      } as unknown as Stripe.Subscription;

      await (service as any).handleSubscriptionUpdated(subscription);

      expect(prisma.subscriptionTier.updateMany).toHaveBeenCalled();
      expect(prisma.organizationUsage.update).toHaveBeenCalled();
      expect(emailService.sendDowngradeWarningEmail).toHaveBeenCalled();
      expect(prisma.auditLog.create).toHaveBeenCalledWith({
        data: expect.objectContaining({
          organizationId,
          action: 'subscription_updated',
        }),
      });
    });

    it('handles subscription deleted and applies downgrade warning when over limit', async () => {
      prisma.organizationUsage.findUnique.mockResolvedValue({
        totalSkus: 9999,
      });

      const subscription = {
        id: 'sub_deleted',
        customer: customerId,
      } as unknown as Stripe.Subscription;

      await (service as any).handleSubscriptionDeleted(subscription);

      expect(prisma.subscriptionTier.updateMany).toHaveBeenCalledWith({
        where: { organizationId },
        data: expect.objectContaining({
          status: SubscriptionStatus.CANCELED,
          tierLevel: 'starter',
        }),
      });
      expect(emailService.sendDowngradeWarningEmail).toHaveBeenCalled();
      expect(prisma.auditLog.create).toHaveBeenCalledWith({
        data: expect.objectContaining({
          organizationId,
          action: 'subscription_canceled',
        }),
      });
    });

    it('handles checkout session completed', async () => {
      const session = {
        id: 'cs_test_123',
        customer: customerId,
        subscription: 'sub_test_123',
      } as unknown as Stripe.Checkout.Session;

      await (service as any).handleCheckoutSessionCompleted(session);

      expect(prisma.subscriptionTier.updateMany).toHaveBeenCalledWith({
        where: {
          organizationId,
          stripeSubscriptionId: 'sub_test_123',
        },
        data: expect.objectContaining({
          trialEndDate: null,
          status: SubscriptionStatus.ACTIVE,
        }),
      });
      expect(prisma.auditLog.create).toHaveBeenCalledWith({
        data: expect.objectContaining({
          organizationId,
          action: 'trial_converted',
        }),
      });
    });

    it('handles invoice payment failed', async () => {
      const invoice = {
        id: 'in_test_123',
        customer: customerId,
        amount_due: 5000,
        hosted_invoice_url: 'https://invoice.test',
      } as unknown as Stripe.Invoice;

      await (service as any).handleInvoicePaymentFailed(invoice);

      expect(prisma.subscriptionTier.updateMany).toHaveBeenCalledWith({
        where: { organizationId },
        data: { status: SubscriptionStatus.PAST_DUE },
      });
      expect(prisma.auditLog.create).toHaveBeenCalledWith({
        data: expect.objectContaining({
          organizationId,
          action: 'payment_failed',
        }),
      });
      expect(emailService.sendDunningEmail).toHaveBeenCalledWith(
        organizationId,
        invoice.hosted_invoice_url,
      );
    });

    it('handles trial will end', async () => {
      const trialEndSeconds = Math.floor(Date.now() / 1000) + 3 * 24 * 60 * 60;
      const subscription = {
        id: 'sub_trial',
        customer: customerId,
        trial_end: trialEndSeconds,
      } as unknown as Stripe.Subscription;

      await (service as any).handleTrialWillEnd(subscription);

      expect(emailService.sendTrialReminderEmail).toHaveBeenCalledWith(
        organizationId,
        expect.any(Number),
      );
    });

    it('records webhook metrics on successful subscription created', async () => {
      const monitor =
        require('../../services/application.monitoring.service').ApplicationMonitoringService.getInstance();
      // reset webhook metrics
      (monitor as any).metrics.webhook = { total: 0, byEvent: {}, idempotencySkips: 0 };

      prisma.subscriptionTier.create.mockResolvedValue({ id: 1 });
      prisma.organizationUsage.upsert.mockResolvedValue({ id: 1 });
      prisma.auditLog.create.mockResolvedValue({ id: 1 });

      const subscription = {
        id: 'sub_created_metrics',
        customer: customerId,
        status: 'active',
        items: {
          data: [
            {
              price: {
                recurring: { interval: 'month' },
                metadata: { tier: 'starter' },
              },
            },
          ],
        },
        trial_end: null,
      } as unknown as Stripe.Subscription;

      await (service as any).handleSubscriptionCreated(subscription);

      const wm = monitor.getWebhookMetrics();
      expect(wm.total).toBeGreaterThanOrEqual(1);
      expect(wm.byEvent['customer.subscription.created'].count).toBe(1);
      expect(wm.byEvent['customer.subscription.created'].avgLatencyMs).toBeGreaterThanOrEqual(0);
    });

    it('captures Sentry and records metric when handler errors', async () => {
      const monitor =
        require('../../services/application.monitoring.service').ApplicationMonitoringService.getInstance();
      (monitor as any).metrics.webhook = { total: 0, byEvent: {}, idempotencySkips: 0 };

      prisma.subscriptionTier.create.mockResolvedValue({ id: 1 });
      prisma.organizationUsage.upsert.mockResolvedValue({ id: 1 });
      // Make auditLog.create throw to simulate DB error
      prisma.auditLog.create.mockRejectedValue(new Error('audit failed'));

      const Sentry = require('@sentry/node');
      jest.spyOn(Sentry, 'captureException').mockImplementation(() => undefined);

      const subscription = {
        id: 'sub_created_error',
        customer: customerId,
        status: 'active',
        items: {
          data: [
            {
              price: {
                recurring: { interval: 'month' },
                metadata: { tier: 'starter' },
              },
            },
          ],
        },
        trial_end: null,
      } as unknown as Stripe.Subscription;

      await expect((service as any).handleSubscriptionCreated(subscription)).rejects.toThrow();

      expect(Sentry.captureException).toHaveBeenCalled();
      const wm = monitor.getWebhookMetrics();
      expect(wm.byEvent['customer.subscription.created'].failures).toBe(1);
    });
  });

  describe('metadata validation', () => {
    it('throws error when metadata is missing', async () => {
      (mockStripe.customers.retrieve as jest.Mock).mockResolvedValue({
        id: customerId,
        deleted: false,
        metadata: {},
      });

      const subscription = {
        id: 'sub_missing_meta',
        customer: customerId,
        status: 'active',
        items: { data: [] },
      } as unknown as Stripe.Subscription;

      await expect((service as any).handleSubscriptionCreated(subscription)).rejects.toThrow(
        'Missing organizationId in Stripe customer metadata',
      );
    });

    it('throws NotFoundError when organization is missing', async () => {
      prisma.organization.findUnique.mockResolvedValue(null);

      const subscription = {
        id: 'sub_missing_org',
        customer: customerId,
        status: 'active',
        items: { data: [] },
      } as unknown as Stripe.Subscription;

      await expect((service as any).handleSubscriptionCreated(subscription)).rejects.toThrow(
        NotFoundError,
      );
    });
  });
});

import { ProductService } from '../../services/product.service';
import fs from 'fs';
import path from 'path';
import * as XLSX from 'xlsx';
import { PrismaClient } from '@prisma/client';

// Mock Prisma manually
const mockPrisma = {
  product: {
    findUnique: jest.fn(),
    create: jest.fn(),
    findMany: jest.fn(),
    update: jest.fn(),
    delete: jest.fn(),
    upsert: jest.fn(),
  },
  organizationUsage: {
    findUnique: jest
      .fn()
      .mockResolvedValue({ organizationId: 'default-org', totalSkus: 0, maxSkus: 1000 }),
    update: jest.fn(),
  },
  $transaction: jest.fn((callback) => callback(mockPrisma)),
} as unknown as PrismaClient; // Cast to PrismaClient to satisfy type checker

// Mock the module
jest.mock('@prisma/client', () => ({
  PrismaClient: jest.fn(() => mockPrisma),
}));

describe('XLSX Upload Functionality Tests', () => {
  let productService: ProductService;
  let testXLSXPath: string;

  beforeEach(() => {
    // Reset mocks
    jest.clearAllMocks();

    // Reset organizationUsage mock (cleared by clearAllMocks)
    (mockPrisma.organizationUsage.findUnique as jest.Mock).mockResolvedValue({
      organizationId: 'default-org',
      totalSkus: 0,
      maxSkus: 1000,
    });

    // Initialize service with mocked Prisma
    productService = new ProductService(mockPrisma);

    const buildMockProduct = (args: any) => {
      const now = new Date();
      return {
        id: Math.ceil(Math.random() * 1000),
        notes: '',
        createdAt: now,
        updatedAt: now,
        ...args.data,
      };
    };

    // Default implementations
    (mockPrisma.product.findUnique as jest.Mock).mockResolvedValue(null);
    (mockPrisma.product.findMany as jest.Mock).mockResolvedValue([]);
    (mockPrisma.product.create as jest.Mock).mockImplementation((args: any) =>
      Promise.resolve(buildMockProduct(args)),
    );
    (mockPrisma.product.upsert as jest.Mock).mockImplementation((args: any) =>
      Promise.resolve(buildMockProduct({ data: args.create })),
    );

    // Create a temporary XLSX file for testing
    const jsonData = [
      ['SKU', 'Name', 'Cost', 'Barcode'],
      ['TEST001', 'Product 1', '$12.99', '1234567890123'],
      ['TEST002', 'Product 2', '€15.50', '1234567890124'],
      ['TEST003', 'Product 3', '100.99', '1234567890125'],
    ];

    const worksheet = XLSX.utils.aoa_to_sheet(jsonData);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, 'Products');

    testXLSXPath = path.join(__dirname, 'test.xlsx');
    XLSX.writeFile(workbook, testXLSXPath);
  });

  afterEach(() => {
    if (fs.existsSync(testXLSXPath)) {
      fs.unlinkSync(testXLSXPath);
    }
    const otherFiles = [
      'test_alt_headers.xlsx',
      'test_missing_fields.xlsx',
      'test_invalid_cost.xlsx',
      'test_missing_headers.xlsx',
      'test_unexpected_columns.xlsx',
      'test_validation.xlsx',
    ];
    otherFiles.forEach((file) => {
      const p = path.join(__dirname, file);
      if (fs.existsSync(p)) fs.unlinkSync(p);
    });
  });

  it('should process XLSX with basic format correctly', async () => {
    const result = await productService.processCSVUpload(testXLSXPath);

    if (result.errors.length > 0) {
      console.log('XLSX Upload Errors:', JSON.stringify(result.errors, null, 2));
    }

    expect(result.errors.length).toBe(0);
    expect(result.imported).toBe(3);
    expect(result.updated).toBe(0);
    expect(mockPrisma.product.create).toHaveBeenCalledTimes(3);
  });

  it('should process XLSX with alternative header names', async () => {
    const jsonData = [
      ['Item Code', 'Product Name', 'Unit Price', 'GTIN'],
      ['TEST001', 'Product 1', '$12.99', '1234567890123'],
      ['TEST002', 'Product 2', '€15.50', '1234567890124'],
    ];

    const worksheet = XLSX.utils.aoa_to_sheet(jsonData);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, 'Products');

    const testAltXLSXPath = path.join(__dirname, 'test_alt_headers.xlsx');
    XLSX.writeFile(workbook, testAltXLSXPath);

    const result = await productService.processCSVUpload(testAltXLSXPath);

    expect(result.errors.length).toBe(0);
    expect(result.imported).toBe(2);
    expect(result.updated).toBe(0);
  });

  it('should return errors for missing required fields in XLSX', async () => {
    const jsonData = [
      ['SKU', 'Name', 'Cost'],
      ['TEST001', 'Product 1', '12.99'],
    ];

    const worksheet = XLSX.utils.aoa_to_sheet(jsonData);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, 'Products');

    const testMissingFieldsPath = path.join(__dirname, 'test_missing_fields.xlsx');
    XLSX.writeFile(workbook, testMissingFieldsPath);

    const result = await productService.processCSVUpload(testMissingFieldsPath);

    expect(result.errors.length).toBeGreaterThan(0);
    expect(result.errors[0]).toContain('Missing required field - Barcode');
    expect(result.imported).toBe(0);
    expect(result.updated).toBe(0);
  });

  it('should return errors for invalid cost values in XLSX', async () => {
    const jsonData = [
      ['SKU', 'Name', 'Cost', 'Barcode'],
      ['TEST001', 'Product 1', 'invalid_cost', '1234567890123'],
    ];

    const worksheet = XLSX.utils.aoa_to_sheet(jsonData);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, 'Products');

    const testInvalidCostPath = path.join(__dirname, 'test_invalid_cost.xlsx');
    XLSX.writeFile(workbook, testInvalidCostPath);

    const result = await productService.processCSVUpload(testInvalidCostPath);

    expect(result.errors.length).toBeGreaterThan(0);
    expect(result.errors[0]).toContain('Invalid cost value');
    expect(result.imported).toBe(0);
    expect(result.updated).toBe(0);
  });

  it('should return errors when required headers are missing in XLSX', async () => {
    const jsonData = [
      ['WrongHeader1', 'WrongHeader2', 'WrongHeader3', 'WrongHeader4'],
      ['TEST001', 'Product 1', '12.99', '1234567890123'],
    ];

    const worksheet = XLSX.utils.aoa_to_sheet(jsonData);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, 'Products');

    const testMissingHeadersPath = path.join(__dirname, 'test_missing_headers.xlsx');
    XLSX.writeFile(workbook, testMissingHeadersPath);

    const result = await productService.processCSVUpload(testMissingHeadersPath);

    expect(result.errors.length).toBeGreaterThan(0);
    expect(result.errors[0]).toContain('Missing required column');
    expect(result.imported).toBe(0);
    expect(result.updated).toBe(0);
